{
  "name": "BillTrack Pro",
  "description": "A comprehensive billing and recovery management system for shop tracking, featuring real-time balance calculations, recovery logging, and financial insights.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum BillType {
  CASH = 'Cash',
  CREDIT = 'Credit',
  INSTALLMENT = 'Installment'
}

export enum PaymentType {
  CASH = 'Cash',
  CHEQUE = 'Cheque',
  ONLINE = 'Online Transfer'
}

export interface Bill {
  id: string;
  date: string;
  customerCode: string;
  obCode: string;
  billNumber: string;
  shopName: string;
  shopAddress: string;
  billType: BillType;
  billAmount: number;
  recovery: number; // Sum of all recoveries for this bill
  balance: number;  // Current balance (Amount - Recovery)
}

export interface Recovery {
  id: string;
  billNumber: string;
  billDate: string;
  recoveryDate: string;
  type: PaymentType;
  billAmountAtRecovery: number; // Balance before this recovery
  recoveryAmount: number;
  remainingAmount: number;    // Balance after this recovery
}

export interface AppState {
  bills: Bill[];
  recoveries: Recovery[];
}

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, BillType, PaymentType } from './types';
import Dashboard from './components/Dashboard';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'bills' | 'recovery' | 'ledger'>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);

  // LocalStorage Persistence
  useEffect(() => {
    const savedBills = localStorage.getItem('bt_bills');
    const savedRecoveries = localStorage.getItem('bt_recoveries');
    if (savedBills) setBills(JSON.parse(savedBills));
    if (savedRecoveries) setRecoveries(JSON.parse(savedRecoveries));
  }, []);

  useEffect(() => {
    localStorage.setItem('bt_bills', JSON.stringify(bills));
    localStorage.setItem('bt_recoveries', JSON.stringify(recoveries));
  }, [bills, recoveries]);

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const newBill: Bill = {
      ...bill,
      id: crypto.randomUUID(),
      recovery: 0,
      balance: bill.billAmount
    };
    setBills(prev => [newBill, ...prev]);
    setActiveTab('ledger');
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const newRecovery: Recovery = {
      ...recovery,
      id: crypto.randomUUID()
    };

    // Update the bill's state
    setBills(prevBills => prevBills.map(b => {
      if (b.billNumber === recovery.billNumber) {
        const updatedRecovery = b.recovery + recovery.recoveryAmount;
        return {
          ...b,
          recovery: updatedRecovery,
          balance: b.billAmount - updatedRecovery
        };
      }
      return b;
    }));

    setRecoveries(prev => [newRecovery, ...prev]);
    setActiveTab('ledger');
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <nav className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 p-6 flex flex-col">
        <div className="flex items-center gap-2 mb-10">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold text-white">B</div>
          <h1 className="text-xl font-bold tracking-tight">BillTrack Pro</h1>
        </div>

        <div className="space-y-2 flex-grow">
          <NavItem 
            active={activeTab === 'dashboard'} 
            onClick={() => setActiveTab('dashboard')} 
            label="Dashboard" 
            icon={<DashboardIcon />} 
          />
          <NavItem 
            active={activeTab === 'bills'} 
            onClick={() => setActiveTab('bills')} 
            label="New Bill" 
            icon={<PlusIcon />} 
          />
          <NavItem 
            active={activeTab === 'recovery'} 
            onClick={() => setActiveTab('recovery')} 
            label="Post Recovery" 
            icon={<RecoveryIcon />} 
          />
          <NavItem 
            active={activeTab === 'ledger'} 
            onClick={() => setActiveTab('ledger')} 
            label="Ledger" 
            icon={<BookIcon />} 
          />
        </div>

        <div className="mt-auto pt-6 border-t border-slate-800">
          <p className="text-xs text-slate-400">v1.0.4 - Senior Build</p>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-grow p-4 md:p-8 overflow-y-auto">
        <div className="max-w-6xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard bills={bills} recoveries={recoveries} />}
          {activeTab === 'bills' && <BillForm onSubmit={addBill} />}
          {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
          {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} />}
        </div>
      </main>
    </div>
  );
};

const NavItem: React.FC<{ active: boolean; onClick: () => void; label: string; icon: React.ReactNode }> = ({ active, onClick, label, icon }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
      active ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
    }`}
  >
    {icon}
    <span className="font-medium">{label}</span>
  </button>
);

// Icons
const DashboardIcon = () => <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>;
const PlusIcon = () => <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>;
const RecoveryIcon = () => <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>;
const BookIcon = () => <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>;

export default App;

import React from 'react';
import { Bill, Recovery } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface DashboardProps {
  bills: Bill[];
  recoveries: Recovery[];
}

const Dashboard: React.FC<DashboardProps> = ({ bills, recoveries }) => {
  const totalSales = bills.reduce((sum, b) => sum + b.billAmount, 0);
  const totalRecovery = recoveries.reduce((sum, r) => sum + r.recoveryAmount, 0);
  const totalOutstanding = totalSales - totalRecovery;

  const chartData = bills.slice(0, 7).reverse().map(b => ({
    name: b.billNumber,
    amount: b.billAmount,
    recovery: b.recovery,
    balance: b.balance
  }));

  const pieData = [
    { name: 'Recovered', value: totalRecovery, color: '#3b82f6' },
    { name: 'Outstanding', value: totalOutstanding, color: '#f43f5e' }
  ];

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Insights Overview</h2>
          <p className="text-slate-500 mt-1">Real-time performance tracking for all shop accounts.</p>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
          label="Total Billing" 
          value={`$${totalSales.toLocaleString()}`} 
          color="blue"
          icon={<BillingIcon />}
        />
        <StatCard 
          label="Total Recovery" 
          value={`$${totalRecovery.toLocaleString()}`} 
          color="emerald" 
          icon={<RecoveryIcon />}
        />
        <StatCard 
          label="Total Outstanding" 
          value={`$${totalOutstanding.toLocaleString()}`} 
          color="rose"
          icon={<AlertIcon />}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Trend Chart */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
            <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
            Recent Billing Trend
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}} 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                />
                <Bar dataKey="amount" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Bill Amount" />
                <Bar dataKey="recovery" fill="#10b981" radius={[4, 4, 0, 0]} name="Recovery" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Recovery Breakdown */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center">
          <h3 className="text-lg font-bold mb-6 self-start flex items-center gap-2">
            <span className="w-1 h-6 bg-rose-500 rounded-full"></span>
            Recovery Status
          </h3>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex gap-8 mt-4">
            {pieData.map(d => (
              <div key={d.name} className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full" style={{backgroundColor: d.color}}></div>
                <span className="text-sm font-medium text-slate-600">{d.name}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; color: 'blue' | 'emerald' | 'rose'; icon: React.ReactNode }> = ({ label, value, color, icon }) => {
  const colors = {
    blue: 'bg-blue-50 text-blue-600',
    emerald: 'bg-emerald-50 text-emerald-600',
    rose: 'bg-rose-50 text-rose-600'
  };
  return (
    <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
      <div className="flex items-center justify-between mb-4">
        <div className={`p-3 rounded-2xl ${colors[color]}`}>{icon}</div>
      </div>
      <p className="text-slate-500 text-sm font-medium">{label}</p>
      <h4 className="text-2xl font-bold mt-1">{value}</h4>
    </div>
  );
};

const BillingIcon = () => <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>;
const RecoveryIcon = () => <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const AlertIcon = () => <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>;

export default Dashboard;

import React, { useState } from 'react';
import { BillType, Bill } from '../types';

interface BillFormProps {
  onSubmit: (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => void;
}

const BillForm: React.FC<BillFormProps> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    customerCode: '',
    obCode: '',
    billNumber: `BILL-${Math.floor(1000 + Math.random() * 9000)}`,
    shopName: '',
    shopAddress: '',
    billType: BillType.CREDIT,
    billAmount: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.billAmount || isNaN(Number(formData.billAmount))) return;

    onSubmit({
      ...formData,
      billAmount: Number(formData.billAmount)
    });
  };

  return (
    <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 max-w-4xl mx-auto animate-slideUp">
      <div className="mb-8">
        <h2 className="text-2xl font-extrabold text-slate-900">New Bill Entry</h2>
        <p className="text-slate-500">Enter the primary billing information for the customer.</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <FormGroup label="Bill Date">
          <input 
            type="date" 
            value={formData.date} 
            onChange={e => setFormData({...formData, date: e.target.value})}
            className="input-base"
          />
        </FormGroup>

        <FormGroup label="Customer Code">
          <input 
            type="text" 
            placeholder="CUST-001"
            value={formData.customerCode} 
            onChange={e => setFormData({...formData, customerCode: e.target.value})}
            className="input-base uppercase"
            required
          />
        </FormGroup>

        <FormGroup label="OB Code (Opening Balance)">
          <input 
            type="text" 
            placeholder="OB-X22"
            value={formData.obCode} 
            onChange={e => setFormData({...formData, obCode: e.target.value})}
            className="input-base uppercase"
            required
          />
        </FormGroup>

        <FormGroup label="Bill Number">
          <input 
            type="text" 
            value={formData.billNumber} 
            readOnly
            className="input-base bg-slate-50 text-slate-400"
          />
        </FormGroup>

        <FormGroup label="Shop Name">
          <input 
            type="text" 
            placeholder="Main Street Hardware"
            value={formData.shopName} 
            onChange={e => setFormData({...formData, shopName: e.target.value})}
            className="input-base"
            required
          />
        </FormGroup>

        <FormGroup label="Shop Address">
          <input 
            type="text" 
            placeholder="123 Commerce St, Downtown"
            value={formData.shopAddress} 
            onChange={e => setFormData({...formData, shopAddress: e.target.value})}
            className="input-base"
            required
          />
        </FormGroup>

        <FormGroup label="Bill Type">
          <select 
            value={formData.billType} 
            onChange={e => setFormData({...formData, billType: e.target.value as BillType})}
            className="input-base"
          >
            {Object.values(BillType).map(type => (
              <option key={type} value={type}>{type}</option>
            ))}
          </select>
        </FormGroup>

        <FormGroup label="Bill Amount ($)">
          <input 
            type="number" 
            placeholder="0.00"
            value={formData.billAmount} 
            onChange={e => setFormData({...formData, billAmount: e.target.value})}
            className="input-base font-bold text-lg text-blue-600"
            required
          />
        </FormGroup>

        <div className="md:col-span-2 pt-4">
          <button 
            type="submit"
            className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all shadow-lg hover:shadow-slate-200 active:scale-[0.98]"
          >
            Create Bill
          </button>
        </div>
      </form>

      <style>{`
        .input-base {
          width: 100%;
          padding: 12px 16px;
          border-radius: 12px;
          border: 1px solid #e2e8f0;
          background-color: white;
          transition: all 0.2s;
          outline: none;
        }
        .input-base:focus {
          border-color: #3b82f6;
          box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
        }
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-slideUp {
          animation: slideUp 0.4s ease-out forwards;
        }
      `}</style>
    </div>
  );
};

const FormGroup: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
  <div className="flex flex-col gap-1.5">
    <label className="text-sm font-semibold text-slate-700 ml-1">{label}</label>
    {children}
  </div>
);

export default BillForm;

import React, { useState, useEffect } from 'react';
import { PaymentType, Bill, Recovery } from '../types';

interface RecoveryFormProps {
  bills: Bill[];
  onSubmit: (recovery: Omit<Recovery, 'id'>) => void;
}

const RecoveryForm: React.FC<RecoveryFormProps> = ({ bills, onSubmit }) => {
  const [selectedBillId, setSelectedBillId] = useState('');
  const [formData, setFormData] = useState({
    recoveryDate: new Date().toISOString().split('T')[0],
    type: PaymentType.CASH,
    recoveryAmount: ''
  });

  const selectedBill = bills.find(b => b.id === selectedBillId);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBill || !formData.recoveryAmount) return;

    const amount = Number(formData.recoveryAmount);
    if (amount > selectedBill.balance) {
      alert("Recovery amount cannot exceed remaining balance!");
      return;
    }

    onSubmit({
      billNumber: selectedBill.billNumber,
      billDate: selectedBill.date,
      recoveryDate: formData.recoveryDate,
      type: formData.type,
      billAmountAtRecovery: selectedBill.balance,
      recoveryAmount: amount,
      remainingAmount: selectedBill.balance - amount
    });
  };

  return (
    <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 max-w-4xl mx-auto animate-slideUp">
      <div className="mb-8">
        <h2 className="text-2xl font-extrabold text-slate-900">Post Recovery</h2>
        <p className="text-slate-500">Record a payment received for an existing bill.</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <FormGroup label="Select Bill">
            <select 
              className="input-base"
              value={selectedBillId}
              onChange={e => setSelectedBillId(e.target.value)}
              required
            >
              <option value="">-- Select a Bill to Recover --</option>
              {bills.filter(b => b.balance > 0).map(b => (
                <option key={b.id} value={b.id}>
                  {b.billNumber} - {b.shopName} (Bal: ${b.balance})
                </option>
              ))}
            </select>
          </FormGroup>

          <FormGroup label="Recovery Date">
            <input 
              type="date" 
              value={formData.recoveryDate} 
              onChange={e => setFormData({...formData, recoveryDate: e.target.value})}
              className="input-base"
              required
            />
          </FormGroup>
        </div>

        {selectedBill && (
          <div className="bg-slate-50 p-6 rounded-2xl border border-slate-200 grid grid-cols-2 md:grid-cols-4 gap-4 animate-fadeIn">
            <div>
              <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Bill Date</p>
              <p className="font-semibold">{selectedBill.date}</p>
            </div>
            <div>
              <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Bill Type</p>
              <p className="font-semibold">{selectedBill.billType}</p>
            </div>
            <div>
              <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Current Balance</p>
              <p className="font-bold text-blue-600">${selectedBill.balance.toLocaleString()}</p>
            </div>
            <div>
              <p className="text-xs text-slate-500 uppercase font-bold tracking-wider">Customer</p>
              <p className="font-semibold truncate">{selectedBill.shopName}</p>
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <FormGroup label="Payment Mode">
            <select 
              value={formData.type} 
              onChange={e => setFormData({...formData, type: e.target.value as PaymentType})}
              className="input-base"
            >
              {Object.values(PaymentType).map(type => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </FormGroup>

          <FormGroup label="Recovery Amount ($)">
            <input 
              type="number" 
              placeholder="0.00"
              value={formData.recoveryAmount} 
              onChange={e => setFormData({...formData, recoveryAmount: e.target.value})}
              className="input-base font-bold text-lg text-emerald-600"
              required
            />
          </FormGroup>
        </div>

        {selectedBill && formData.recoveryAmount && !isNaN(Number(formData.recoveryAmount)) && (
          <div className="flex justify-between items-center p-4 bg-blue-50 border border-blue-100 rounded-xl">
            <span className="text-blue-800 font-medium">Projected Balance After Recovery:</span>
            <span className="text-xl font-bold text-blue-900">
              ${(selectedBill.balance - Number(formData.recoveryAmount)).toLocaleString()}
            </span>
          </div>
        )}

        <button 
          type="submit"
          disabled={!selectedBill}
          className="w-full bg-emerald-600 text-white py-4 rounded-2xl font-bold text-lg hover:bg-emerald-700 transition-all shadow-lg hover:shadow-emerald-200 active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Post Recovery Transaction
        </button>
      </form>

      <style>{`
