import React, { useState, useEffect } from 'react';
import { BillType, Bill, Customer, OrderBooker } from '../types';

interface BillFormProps {
  customers: Customer[];
  obs: OrderBooker[];
  onSubmit: (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => void;
}

const BillForm: React.FC<BillFormProps> = ({ customers, obs, onSubmit }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    customerCode: '',
    obCode: '',
    billNumber: `B-${Math.floor(10000 + Math.random() * 90000)}`,
    shopName: '',
    shopAddress: '',
    billType: BillType.CREDIT,
    billAmount: ''
  });

  // Auto-fill logic
  useEffect(() => {
    const customer = customers.find(c => c.code.toLowerCase() === formData.customerCode.toLowerCase());
    if (customer) {
      setFormData(prev => ({
        ...prev,
        shopName: customer.name,
        shopAddress: customer.address
      }));
    }
  }, [formData.customerCode, customers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.billAmount || isNaN(Number(formData.billAmount))) return;
    onSubmit({ ...formData, billAmount: Number(formData.billAmount) });
  };

  return (
    <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100 max-w-4xl mx-auto animate-slideUp">
      <div className="mb-8">
        <h2 className="text-2xl font-extrabold text-slate-900">New Bill Entry</h2>
        <p className="text-slate-500">Auto-populates shop data based on Customer Code.</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <FormGroup label="Bill Date">
          <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="input-base" />
        </FormGroup>

        <FormGroup label="Customer Code">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Enter Code (e.g. C001)"
              value={formData.customerCode} 
              onChange={e => setFormData({...formData, customerCode: e.target.value})}
              className={`input-base uppercase ${customers.some(c => c.code === formData.customerCode) ? 'border-emerald-500 ring-emerald-100 ring-2' : ''}`}
              required
            />
            {customers.some(c => c.code === formData.customerCode) && (
              <span className="absolute right-3 top-1/2 -translate-y-1/2 text-emerald-500 text-xs font-bold">MATCHED</span>
            )}
          </div>
        </FormGroup>

        <FormGroup label="Order Booker (OB)">
          <select 
            value={formData.obCode} 
            onChange={e => setFormData({...formData, obCode: e.target.value})}
            className="input-base"
            required
          >
            <option value="">Select OB</option>
            {obs.map(ob => (
              <option key={ob.id} value={ob.code}>{ob.name} ({ob.code})</option>
            ))}
          </select>
        </FormGroup>

        <FormGroup label="Bill Number">
          <input type="text" value={formData.billNumber} readOnly className="input-base bg-slate-50 text-slate-400" />
        </FormGroup>

        <FormGroup label="Shop Name">
          <input type="text" value={formData.shopName} onChange={e => setFormData({...formData, shopName: e.target.value})} className="input-base" required />
        </FormGroup>

        <FormGroup label="Shop Address">
          <input type="text" value={formData.shopAddress} onChange={e => setFormData({...formData, shopAddress: e.target.value})} className="input-base" required />
        </FormGroup>

        <FormGroup label="Bill Type">
          <select value={formData.billType} onChange={e => setFormData({...formData, billType: e.target.value as BillType})} className="input-base">
            {Object.values(BillType).map(type => <option key={type} value={type}>{type}</option>)}
          </select>
        </FormGroup>

        <FormGroup label="Bill Amount ($)">
          <input type="number" placeholder="0.00" value={formData.billAmount} onChange={e => setFormData({...formData, billAmount: e.target.value})} className="input-base font-bold text-lg text-blue-600" required />
        </FormGroup>

        <div className="md:col-span-2 pt-4">
          <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all shadow-lg">Create Bill</button>
        </div>
      </form>

      <style>{`
        .input-base { width: 100%; padding: 12px 16px; border-radius: 12px; border: 1px solid #e2e8f0; background-color: white; transition: all 0.2s; outline: none; }
        .input-base:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1); }
      `}</style>
    </div>
  );
};

const FormGroup: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
  <div className="flex flex-col gap-1.5">
    <label className="text-sm font-semibold text-slate-700 ml-1">{label}</label>
    {children}
  </div>
);

export default BillForm;

import React, { useState } from 'react';
import { Customer } from '../types';

interface Props {
  customers: Customer[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
}

const CustomerForm: React.FC<Props> = ({ customers, setCustomers }) => {
  const [formData, setFormData] = useState({ code: '', name: '', address: '' });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (customers.some(c => c.code === formData.code)) {
      alert("Code already exists!");
      return;
    }
    setCustomers(prev => [...prev, { ...formData, id: crypto.randomUUID() }]);
    setFormData({ code: '', name: '', address: '' });
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-slate-100">
        <h2 className="text-2xl font-bold mb-6">Register New Customer</h2>
        <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
          <div>
            <label className="text-xs font-bold text-slate-500 uppercase ml-1">Customer Code</label>
            <input type="text" value={formData.code} onChange={e => setFormData({...formData, code: e.target.value.toUpperCase()})} className="input-base mt-1" placeholder="e.g. C001" required />
          </div>
          <div>
            <label className="text-xs font-bold text-slate-500 uppercase ml-1">Shop Name</label>
