import React from 'react';
import { Bill, OrderBooker } from '../types';

interface Props {
  bills: Bill[];
  obs: OrderBooker[];
}

const Summary: React.FC<Props> = ({ bills, obs }) => {
  const summaryData = obs.map(ob => {
    const obBills = bills.filter(b => b.obCode === ob.code);
    const totalSales = obBills.reduce((s, b) => s + b.billAmount, 0);
    const totalBalance = obBills.reduce((s, b) => s + b.balance, 0);
    const totalRecovery = totalSales - totalBalance;
    const recoveryRate = totalSales ? Math.round((totalRecovery / totalSales) * 100) : 0;

    return {
      ...ob,
      totalSales,
      totalBalance,
      totalRecovery,
      recoveryRate
    };
  });

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="flex flex-col">
        <h2 className="text-3xl font-extrabold text-slate-900 tracking-tighter">Credit Performance</h2>
        <p className="text-slate-500">Breakdown of recovery and outstanding balances by Order Booker.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {summaryData.map(data => (
          <div key={data.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-none">{data.name}</h3>
                <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase">{data.code}</span>
              </div>
              <div className={`px-2 py-1 rounded-lg text-[10px] font-black ${data.recoveryRate > 70 ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                {data.recoveryRate}% RECOVERY
              </div>
            </div>

            <div className="space-y-4">
              <StatRow label="Total Billing" value={`$${data.totalSales.toLocaleString()}`} />
              <StatRow label="Total Recovery" value={`$${data.totalRecovery.toLocaleString()}`} color="text-emerald-600" />
              <div className="h-px bg-slate-50 w-full" />
              <StatRow label="Outstanding Balance" value={`$${data.totalBalance.toLocaleString()}`} color="text-rose-600" bold />
            </div>

            <div className="mt-6 w-full bg-slate-100 h-2 rounded-full overflow-hidden">
              <div className="bg-blue-600 h-full transition-all" style={{width: `${data.recoveryRate}%`}} />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

const StatRow = ({ label, value, color = "text-slate-900", bold = false }: any) => (
  <div className="flex justify-between items-center text-sm">
    <span className="text-slate-500 font-medium">{label}</span>
    <span className={`${color} ${bold ? 'font-black' : 'font-bold'}`}>{value}</span>
  </div>
);

