import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker } from './types';
import Dashboard from './components/Dashboard';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);

  // State for editing
  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  useEffect(() => {
    const load = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
    setBills(load('bt_bills'));
    setRecoveries(load('bt_recoveries'));
    setCustomers(load('bt_customers'));
    setObs(load('bt_obs'));
  }, []);

  useEffect(() => {
    localStorage.setItem('bt_bills', JSON.stringify(bills));
    localStorage.setItem('bt_recoveries', JSON.stringify(recoveries));
    localStorage.setItem('bt_customers', JSON.stringify(customers));
    localStorage.setItem('bt_obs', JSON.stringify(obs));
  }, [bills, recoveries, customers, obs]);

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const newBill: Bill = { ...bill, id: crypto.randomUUID(), recovery: 0, balance: bill.billAmount };
    setBills(prev => [newBill, ...prev]);
    setActiveTab('ledger');
  };

  const updateBill = (updatedBill: Bill) => {
    setBills(prev => prev.map(b => b.id === updatedBill.id ? updatedBill : b));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Are you sure you want to delete this bill? This will also remove associated recovery records.")) {
      const billToDelete = bills.find(b => b.id === id);
      if (billToDelete) {
        setRecoveries(prev => prev.filter(r => r.billNumber !== billToDelete.billNumber));
      }
      setBills(prev => prev.filter(b => b.id !== id));
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const newRecovery: Recovery = { ...recovery, id: crypto.randomUUID() };
    setBills(prev => prev.map(b => {
      if (b.billNumber === recovery.billNumber) {
        const totalRec = b.recovery + recovery.recoveryAmount;
        return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
      }
      return b;
    }));
    setRecoveries(prev => [newRecovery, ...prev]);
    setActiveTab('ledger');
  };

  const updateRecovery = (updatedRecovery: Recovery) => {
    const oldRecovery = recoveries.find(r => r.id === updatedRecovery.id);
    if (!oldRecovery) return;

    setBills(prev => prev.map(b => {
      if (b.billNumber === updatedRecovery.billNumber) {
        const adjustedRecovery = b.recovery - oldRecovery.recoveryAmount + updatedRecovery.recoveryAmount;
        return { ...b, recovery: adjustedRecovery, balance: b.billAmount - adjustedRecovery };
      }
      return b;
    }));

    setRecoveries(prev => prev.map(r => r.id === updatedRecovery.id ? updatedRecovery : r));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery record? The bill balance will be updated.")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        setBills(prev => prev.map(b => {
          if (b.billNumber === rec.billNumber) {
            const totalRec = b.recovery - rec.recoveryAmount;
            return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
          }
          return b;
        }));
      }
      setRecoveries(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleEditClick = (type: 'bill' | 'recovery' | 'customer' | 'ob', data: any) => {
    setEditingItem({ type, data });
    setActiveTab('edit');
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <nav className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 p-6 flex flex-col overflow-y-auto max-h-screen sticky top-0">
        <div className="flex items-center gap-2 mb-10">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold text-white">B</div>
          <h1 className="text-xl font-bold tracking-tight">BillTrack Pro</h1>
        </div>

        <div className="space-y-1 flex-grow">
          <p className="text-[10px] uppercase font-bold text-slate-500 mb-2 px-4 tracking-widest">Main</p>
          <NavItem active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} label="Dashboard" icon={<DashIcon />} />
          <NavItem active={activeTab === 'today'} onClick={() => setActiveTab('today')} label="Today's Activity" icon={<TodayIcon />} />
          <NavItem active={activeTab === 'summary'} onClick={() => setActiveTab('summary')} label="OB Summary" icon={<ChartIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Operations</p>
          <NavItem active={activeTab === 'bills'} onClick={() => setActiveTab('bills')} label="Billing" icon={<PlusIcon />} />
          <NavItem active={activeTab === 'recovery'} onClick={() => setActiveTab('recovery')} label="Recovery" icon={<RecIcon />} />
          <NavItem active={activeTab === 'ledger'} onClick={() => setActiveTab('ledger')} label="Ledger" icon={<BookIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Master Data</p>
          <NavItem active={activeTab === 'customers'} onClick={() => setActiveTab('customers')} label="Customers" icon={<UserIcon />} />
          <NavItem active={activeTab === 'obs'} onClick={() => setActiveTab('obs')} label="Order Bookers" icon={<BriefcaseIcon />} />
          <NavItem active={activeTab === 'import'} onClick={() => setActiveTab('import')} label="Import Data" icon={<ImportIcon />} />

          {editingItem && (
            <div className="mt-4 pt-4 border-t border-slate-800">
               <NavItem active={activeTab === 'edit'} onClick={() => setActiveTab('edit')} label="Continue Editing" icon={<EditIcon />} />
            </div>
          )}
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-8 overflow-y-auto">
        <div className="max-w-6xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard bills={bills} recoveries={recoveries} />}
          {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
          {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
          {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
          {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
          {activeTab === 'ledger' && (
            <Ledger 
              bills={bills} 
              recoveries={recoveries} 
              onEditBill={(b) => handleEditClick('bill', b)} 
              onDeleteBill={deleteBill}
              onEditRecovery={(r) => handleEditClick('recovery', r)}
              onDeleteRecovery={deleteRecovery}
            />
          )}
          {activeTab === 'customers' && (
            <CustomerForm 
              customers={customers} 
              setCustomers={setCustomers} 
              onEdit={(c) => handleEditClick('customer', c)}
            />
          )}
          {activeTab === 'obs' && (
            <OrderBookerForm 
              obs={obs} 
              setObs={setObs} 
              onEdit={(ob) => handleEditClick('ob', ob)}
            />
          )}
          {activeTab === 'import' && <ImportPage />}
          {activeTab === 'edit' && editingItem && (
            <EditEntryPage 
              item={editingItem} 
              customers={customers} 
              obs={obs}
              bills={bills}
              onUpdateBill={updateBill}
              onUpdateRecovery={updateRecovery}
              onUpdateCustomer={(c) => {
                setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
                setEditingItem(null);
                setActiveTab('customers');
              }}
              onUpdateOB={(ob) => {
                setObs(prev => prev.map(item => item.id === ob.id ? ob : item));
                setEditingItem(null);
                setActiveTab('obs');
              }}
              onCancel={() => {
                setEditingItem(null);
                setActiveTab('ledger');
              }}
            />
          )}
        </div>
      </main>
    </div>
  );
};

