import React from 'react';
import { Bill, Recovery, OrderBooker } from '../types';

interface Props {
  bills: Bill[];
  recoveries: Recovery[];
  obs: OrderBooker[];
}

const TodayReport: React.FC<Props> = ({ bills, recoveries, obs }) => {
  const today = new Date().toISOString().split('T')[0];

  // Filter today's data
  const todayBills = bills.filter(b => b.date === today);
  const todayRecoveries = recoveries.filter(r => r.recoveryDate === today);

  // Group by OB
  const obStats = obs.map(ob => {
    const obTodayBills = todayBills.filter(b => b.obCode === ob.code);
    const obTodayRecoveries = todayRecoveries.filter(r => {
      // Find the bill associated with this recovery to get the OB Code
      const linkedBill = bills.find(b => b.billNumber === r.billNumber);
      return linkedBill?.obCode === ob.code;
    });

    const totalCredit = obTodayBills.reduce((sum, b) => sum + b.billAmount, 0);
    const totalRecovery = obTodayRecoveries.reduce((sum, r) => sum + r.recoveryAmount, 0);

    return {
      ...ob,
      totalCredit,
      totalRecovery,
      billCount: obTodayBills.length,
      recCount: obTodayRecoveries.length
    };
  }).filter(stat => stat.totalCredit > 0 || stat.totalRecovery > 0); // Only show active OBs for today

  const grandTotalCredit = obStats.reduce((sum, s) => sum + s.totalCredit, 0);
  const grandTotalRecovery = obStats.reduce((sum, s) => sum + s.totalRecovery, 0);

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter">Today's Activity</h2>
          <p className="text-slate-500 mt-1">Daily credit vs recovery performance by Order Booker.</p>
        </div>
        <div className="bg-white px-4 py-2 rounded-2xl border border-slate-200 shadow-sm flex items-center gap-3">
          <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
          <span className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-blue-600 p-6 rounded-[32px] text-white shadow-xl shadow-blue-200 flex justify-between items-center">
            <div>
                <p className="text-blue-100 text-xs font-bold uppercase tracking-widest">Total Credit (Today)</p>
                <h4 className="text-4xl font-black mt-1">${grandTotalCredit.toLocaleString()}</h4>
            </div>
            <svg className="w-12 h-12 opacity-20" fill="currentColor" viewBox="0 0 24 24"><path d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
        </div>
        <div className="bg-emerald-600 p-6 rounded-[32px] text-white shadow-xl shadow-emerald-200 flex justify-between items-center">
            <div>
                <p className="text-emerald-100 text-xs font-bold uppercase tracking-widest">Total Recovery (Today)</p>
                <h4 className="text-4xl font-black mt-1">${grandTotalRecovery.toLocaleString()}</h4>
            </div>
            <svg className="w-12 h-12 opacity-20" fill="currentColor" viewBox="0 0 24 24"><path d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>
        </div>
      </div>

      <div className="bg-white rounded-[40px] shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-slate-50 text-[10px] text-slate-400 font-black uppercase tracking-widest">
              <th className="px-8 py-6">Order Booker</th>
              <th className="px-8 py-6 text-center">Activity</th>
              <th className="px-8 py-6 text-right">Credit (Bills)</th>
              <th className="px-8 py-6 text-right">Recovery</th>
              <th className="px-8 py-6 text-right">Net Flow</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {obStats.map(stat => {
              const net = stat.totalRecovery - stat.totalCredit;
              return (
                <tr key={stat.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center font-bold text-slate-400">
                            {stat.name.charAt(0)}
                        </div>
                        <div>
                            <p className="font-black text-slate-900">{stat.name}</p>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">{stat.code}</p>
                        </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex justify-center gap-2">
                        <span className="px-2 py-1 bg-blue-50 text-blue-600 rounded-lg text-[10px] font-black">{stat.billCount} BILLS</span>
                        <span className="px-2 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[10px] font-black">{stat.recCount} RECS</span>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-right">
                    <p className="text-lg font-bold text-blue-600">${stat.totalCredit.toLocaleString()}</p>
                  </td>
                  <td className="px-8 py-6 text-right">
                    <p className="text-lg font-bold text-emerald-600">${stat.totalRecovery.toLocaleString()}</p>
                  </td>
                  <td className="px-8 py-6 text-right">
                    <span className={`text-sm font-black px-3 py-1.5 rounded-xl ${net >= 0 ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                        {net >= 0 ? '+' : '-'}${Math.abs(net).toLocaleString()}
                    </span>
                  </td>
                </tr>
              );
            })}
            {obStats.length === 0 && (
              <tr>
                <td colSpan={5} className="px-8 py-20 text-center">
                    <div className="flex flex-col items-center opacity-30">
                        <svg className="w-12 h-12 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <p className="text-lg font-bold">No transactions recorded today.</p>
                        <p className="text-sm">Start by adding a new bill or posting a recovery.</p>
                    </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="bg-slate-900 p-8 rounded-[40px] text-white flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="text-center md:text-left">
            <h4 className="text-xl font-black">Daily Performance Metric</h4>
            <p className="text-slate-400 text-sm mt-1">Today's recovery covers {grandTotalCredit > 0 ? Math.round((grandTotalRecovery / grandTotalCredit) * 100) : 0}% of today's new billing.</p>
        </div>
        <div className="flex gap-4">
            <button onClick={() => window.print()} className="px-6 py-3 bg-white/10 hover:bg-white/20 rounded-2xl text-sm font-bold transition-all border border-white/5">Print Daily Report</button>
        </div>
      </div>
    </div>
  );
};

export default TodayReport;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker } from './types';
import Dashboard from './components/Dashboard';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);

  // State for editing
  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  useEffect(() => {
    const load = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
    setBills(load('bt_bills'));
    setRecoveries(load('bt_recoveries'));
    setCustomers(load('bt_customers'));
    setObs(load('bt_obs'));
  }, []);

  useEffect(() => {
    localStorage.setItem('bt_bills', JSON.stringify(bills));
    localStorage.setItem('bt_recoveries', JSON.stringify(recoveries));
    localStorage.setItem('bt_customers', JSON.stringify(customers));
    localStorage.setItem('bt_obs', JSON.stringify(obs));
  }, [bills, recoveries, customers, obs]);

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const newBill: Bill = { ...bill, id: crypto.randomUUID(), recovery: 0, balance: bill.billAmount };
    setBills(prev => [newBill, ...prev]);
    setActiveTab('ledger');
  };

  const handleBulkImport = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    const preparedBills = newBills.map(b => ({
      ...b,
      id: crypto.randomUUID(),
      recovery: 0,
      balance: b.billAmount
    }));
    setBills(prev => [...preparedBills, ...prev]);
    setActiveTab('ledger');
  };

  const updateBill = (updatedBill: Bill) => {
    setBills(prev => prev.map(b => b.id === updatedBill.id ? updatedBill : b));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Are you sure you want to delete this bill? This will also remove associated recovery records.")) {
      const billToDelete = bills.find(b => b.id === id);
      if (billToDelete) {
        setRecoveries(prev => prev.filter(r => r.billNumber !== billToDelete.billNumber));
      }
      setBills(prev => prev.filter(b => b.id !== id));
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const newRecovery: Recovery = { ...recovery, id: crypto.randomUUID() };
    setBills(prev => prev.map(b => {
      if (b.billNumber === recovery.billNumber) {
        const totalRec = b.recovery + recovery.recoveryAmount;
        return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
      }
      return b;
    }));
    setRecoveries(prev => [newRecovery, ...prev]);
    setActiveTab('ledger');
  };

  const updateRecovery = (updatedRecovery: Recovery) => {
    const oldRecovery = recoveries.find(r => r.id === updatedRecovery.id);
    if (!oldRecovery) return;

    setBills(prev => prev.map(b => {
      if (b.billNumber === updatedRecovery.billNumber) {
        const adjustedRecovery = b.recovery - oldRecovery.recoveryAmount + updatedRecovery.recoveryAmount;
        return { ...b, recovery: adjustedRecovery, balance: b.billAmount - adjustedRecovery };
      }
      return b;
    }));

    setRecoveries(prev => prev.map(r => r.id === updatedRecovery.id ? updatedRecovery : r));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery record? The bill balance will be updated.")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        setBills(prev => prev.map(b => {
          if (b.billNumber === rec.billNumber) {
            const totalRec = b.recovery - rec.recoveryAmount;
            return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
          }
          return b;
        }));
      }
      setRecoveries(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleEditClick = (type: 'bill' | 'recovery' | 'customer' | 'ob', data: any) => {
    setEditingItem({ type, data });
    setActiveTab('edit');
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <nav className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 p-6 flex flex-col overflow-y-auto max-h-screen sticky top-0">
        <div className="flex items-center gap-2 mb-10">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold text-white">B</div>
          <h1 className="text-xl font-bold tracking-tight">BillTrack Pro</h1>
        </div>

        <div className="space-y-1 flex-grow">
          <p className="text-[10px] uppercase font-bold text-slate-500 mb-2 px-4 tracking-widest">Main</p>
          <NavItem active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} label="Dashboard" icon={<DashIcon />} />
          <NavItem active={activeTab === 'today'} onClick={() => setActiveTab('today')} label="Today's Activity" icon={<TodayIcon />} />
          <NavItem active={activeTab === 'summary'} onClick={() => setActiveTab('summary')} label="OB Summary" icon={<ChartIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Operations</p>
          <NavItem active={activeTab === 'bills'} onClick={() => setActiveTab('bills')} label="Billing" icon={<PlusIcon />} />
          <NavItem active={activeTab === 'recovery'} onClick={() => setActiveTab('recovery')} label="Recovery" icon={<RecIcon />} />
          <NavItem active={activeTab === 'ledger'} onClick={() => setActiveTab('ledger')} label="Ledger" icon={<BookIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Master Data</p>
          <NavItem active={activeTab === 'customers'} onClick={() => setActiveTab('customers')} label="Customers" icon={<UserIcon />} />
          <NavItem active={activeTab === 'obs'} onClick={() => setActiveTab('obs')} label="Order Bookers" icon={<BriefcaseIcon />} />
          <NavItem active={activeTab === 'import'} onClick={() => setActiveTab('import')} label="Import Data" icon={<ImportIcon />} />

          {editingItem && (
            <div className="mt-4 pt-4 border-t border-slate-800">
               <NavItem active={activeTab === 'edit'} onClick={() => setActiveTab('edit')} label="Continue Editing" icon={<EditIcon />} />
            </div>
          )}
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-8 overflow-y-auto">
        <div className="max-w-6xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard bills={bills} recoveries={recoveries} />}
          {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
          {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
          {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
          {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
          {activeTab === 'ledger' && (
            <Ledger 
              bills={bills} 
              recoveries={recoveries} 
              onEditBill={(b) => handleEditClick('bill', b)} 
              onDeleteBill={deleteBill}
              onEditRecovery={(r) => handleEditClick('recovery', r)}
              onDeleteRecovery={deleteRecovery}
            />
          )}
          {activeTab === 'customers' && (
            <CustomerForm 
              customers={customers} 
              setCustomers={setCustomers} 
              onEdit={(c) => handleEditClick('customer', c)}
            />
          )}
          {activeTab === 'obs' && (
            <OrderBookerForm 
              obs={obs} 
              setObs={setObs} 
              onEdit={(ob) => handleEditClick('ob', ob)}
            />
          )}
          {activeTab === 'import' && <ImportPage onImport={handleBulkImport} customers={customers} obs={obs} />}
          {activeTab === 'edit' && editingItem && (
            <EditEntryPage 
              item={editingItem} 
              customers={customers} 
              obs={obs}
              bills={bills}
              onUpdateBill={updateBill}
              onUpdateRecovery={updateRecovery}
              onUpdateCustomer={(c) => {
                setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
                setEditingItem(null);
                setActiveTab('customers');
              }}
              onUpdateOB={(ob) => {
                setObs(prev => prev.map(item => item.id === ob.id ? ob : item));
                setEditingItem(null);
                setActiveTab('obs');
              }}
              onCancel={() => {
                setEditingItem(null);
                setActiveTab('ledger');
              }}
            />
          )}
        </div>
      </main>
    </div>
  );
};

