import React, { useState } from 'react';
import { Bill, BillType, Customer, OrderBooker } from '../types';

interface Props {
  onImport: (bills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => void;
  customers: Customer[];
  obs: OrderBooker[];
}

const ImportPage: React.FC<Props> = ({ onImport, customers, obs }) => {
  const [stage, setStage] = useState<'upload' | 'mapping' | 'preview'>('upload');
  const [rawText, setRawText] = useState('');
  const [parsedData, setParsedData] = useState<string[][]>([]);
  const [mapping, setMapping] = useState<Record<string, number>>({});
  const [importResult, setImportResult] = useState<Omit<Bill, 'id' | 'recovery' | 'balance'>[]>([]);

  const fields = [
    { key: 'date', label: 'Bill Date' },
    { key: 'customerCode', label: 'Customer Code' },
    { key: 'obCode', label: 'OB Code' },
    { key: 'billNumber', label: 'Bill Number' },
    { key: 'shopName', label: 'Shop Name (Auto if Code matches)' },
    { key: 'shopAddress', label: 'Shop Address' },
    { key: 'billAmount', label: 'Amount' }
  ];

  const handleTextProcess = () => {
    if (!rawText.trim()) return;
    const lines = rawText.split('\n').map(line => line.split(/[,\t]/).map(cell => cell.trim()));
    setParsedData(lines);
    setStage('mapping');
  };

  const handleStartImport = () => {
    const finalBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[] = parsedData.slice(1).map(row => {
      const customerCode = row[mapping.customerCode] || '';
      const matchedCustomer = customers.find(c => c.code.toLowerCase() === customerCode.toLowerCase());

      return {
        date: row[mapping.date] || new Date().toISOString().split('T')[0],
        customerCode,
        obCode: row[mapping.obCode] || '',
        billNumber: row[mapping.billNumber] || `IMP-${Math.floor(1000 + Math.random() * 9000)}`,
        shopName: matchedCustomer ? matchedCustomer.name : (row[mapping.shopName] || 'Imported Shop'),
        shopAddress: matchedCustomer ? matchedCustomer.address : (row[mapping.shopAddress] || ''),
        billType: BillType.CREDIT,
        billAmount: parseFloat(row[mapping.billAmount]) || 0
      };
    }).filter(b => b.billAmount > 0);

    setImportResult(finalBills);
    setStage('preview');
  };

  const finalize = () => {
    onImport(importResult);
  };

  return (
    <div className="max-w-5xl mx-auto animate-fadeIn">
      {stage === 'upload' && (
        <div className="bg-white p-12 rounded-[40px] shadow-sm border border-slate-100 text-center space-y-8">
          <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter">Bulk Credit Bill Import</h2>
            <p className="text-slate-500 mt-2 max-w-md mx-auto">Paste your Excel/CSV data below. We'll map the columns in the next step.</p>
          </div>

          <textarea 
            className="w-full h-48 p-6 bg-slate-50 rounded-3xl border-2 border-slate-200 focus:border-blue-500 focus:outline-none transition-all font-mono text-sm"
            placeholder="Paste your CSV or Excel content here (including headers)..."
            value={rawText}
            onChange={e => setRawText(e.target.value)}
          />

          <div className="flex gap-4 justify-center">
            <button 
                onClick={handleTextProcess}
                disabled={!rawText}
                className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-bold hover:bg-slate-800 transition-all disabled:opacity-50"
            >
                Process Data
            </button>
          </div>
          <p className="text-xs text-slate-400">Supported: Comma separated, Tab separated (Excel Copy/Paste)</p>
        </div>
      )}

      {stage === 'mapping' && (
        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 animate-slideUp">
            <h2 className="text-2xl font-black text-slate-900 mb-2">Column Mapping</h2>
            <p className="text-slate-500 mb-8">Match your spreadsheet headers to our data fields.</p>

            <div className="space-y-4 max-w-2xl">
                {fields.map(field => (
                    <div key={field.key} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
                        <span className="font-bold text-slate-700">{field.label}</span>
                        <select 
                            className="bg-white border border-slate-200 rounded-xl px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-100"
                            onChange={e => setMapping(prev => ({...prev, [field.key]: parseInt(e.target.value)}))}
                            defaultValue=""
                        >
                            <option value="">Select Column</option>
                            {parsedData[0].map((header, idx) => (
                                <option key={idx} value={idx}>{header || `Column ${idx+1}`}</option>
                            ))}
                        </select>
                    </div>
                ))}
            </div>

            <div className="mt-10 flex gap-4">
                <button onClick={handleStartImport} className="flex-grow bg-blue-600 text-white py-4 rounded-2xl font-black shadow-lg shadow-blue-100">Review Import</button>
                <button onClick={() => setStage('upload')} className="px-8 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold">Back</button>
            </div>
        </div>
      )}

      {stage === 'preview' && (
        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-100 animate-slideUp">
            <div className="flex justify-between items-center mb-8">
                <div>
                    <h2 className="text-2xl font-black text-slate-900">Reviewing {importResult.length} Records</h2>
                    <p className="text-slate-500">Check for accuracy before committing to ledger.</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={finalize} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black shadow-lg shadow-emerald-100">Confirm & Save</button>
                    <button onClick={() => setStage('mapping')} className="bg-slate-100 text-slate-600 px-6 py-3 rounded-2xl font-bold">Edit Mapping</button>
                </div>
            </div>

            <div className="overflow-x-auto border border-slate-100 rounded-3xl">
                <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] uppercase font-bold text-slate-400">
                        <tr>
                            <th className="px-6 py-4">Date</th>
                            <th className="px-6 py-4">Bill #</th>
                            <th className="px-6 py-4">Customer</th>
                            <th className="px-6 py-4">OB Code</th>
                            <th className="px-6 py-4 text-right">Amount</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {importResult.map((b, i) => (
                            <tr key={i} className="text-xs">
                                <td className="px-6 py-4">{b.date}</td>
                                <td className="px-6 py-4 font-bold">{b.billNumber}</td>
                                <td className="px-6 py-4">
                                    <p className="font-medium">{b.shopName}</p>
                                    <p className="text-[10px] text-slate-400">{b.customerCode}</p>
                                </td>
                                <td className="px-6 py-4">{b.obCode}</td>
                                <td className="px-6 py-4 text-right font-black text-slate-900">${b.billAmount.toLocaleString()}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
      )}

      <div className="mt-12 bg-slate-900 text-white p-8 rounded-[40px] relative overflow-hidden">
        <div className="relative z-10 flex flex-col md:flex-row items-center gap-8">
            <div className="w-16 h-16 bg-blue-500 rounded-2xl flex items-center justify-center shrink-0">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            </div>
            <div>
                <h3 className="text-lg font-bold">Import Tip</h3>
                <p className="text-slate-400 text-sm mt-1">If your "Customer Code" matches a registered customer, the Shop Name and Address will be linked automatically. If not, the imported values will be used as a standalone entry.</p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ImportPage;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker } from './types';
import Dashboard from './components/Dashboard';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);

  // State for editing
  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  useEffect(() => {
    const load = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
    setBills(load('bt_bills'));
    setRecoveries(load('bt_recoveries'));
    setCustomers(load('bt_customers'));
    setObs(load('bt_obs'));
  }, []);

  useEffect(() => {
    localStorage.setItem('bt_bills', JSON.stringify(bills));
    localStorage.setItem('bt_recoveries', JSON.stringify(recoveries));
    localStorage.setItem('bt_customers', JSON.stringify(customers));
    localStorage.setItem('bt_obs', JSON.stringify(obs));
  }, [bills, recoveries, customers, obs]);

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const newBill: Bill = { ...bill, id: crypto.randomUUID(), recovery: 0, balance: bill.billAmount };
    setBills(prev => [newBill, ...prev]);
    setActiveTab('ledger');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    const preparedBills = newBills.map(b => ({
      ...b,
      id: crypto.randomUUID(),
      recovery: 0,
      balance: b.billAmount
    }));
    setBills(prev => [...preparedBills, ...prev]);
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    const prepared = newCustomers.map(c => ({
      ...c,
      id: crypto.randomUUID()
    }));
    setCustomers(prev => [...prev, ...prepared]);
    setActiveTab('customers');
  };

  const updateBill = (updatedBill: Bill) => {
    setBills(prev => prev.map(b => b.id === updatedBill.id ? updatedBill : b));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Are you sure you want to delete this bill? This will also remove associated recovery records.")) {
      const billToDelete = bills.find(b => b.id === id);
      if (billToDelete) {
        setRecoveries(prev => prev.filter(r => r.billNumber !== billToDelete.billNumber));
      }
      setBills(prev => prev.filter(b => b.id !== id));
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const newRecovery: Recovery = { ...recovery, id: crypto.randomUUID() };
    setBills(prev => prev.map(b => {
      if (b.billNumber === recovery.billNumber) {
        const totalRec = b.recovery + recovery.recoveryAmount;
        return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
      }
      return b;
    }));
    setRecoveries(prev => [newRecovery, ...prev]);
    setActiveTab('ledger');
  };

  const updateRecovery = (updatedRecovery: Recovery) => {
    const oldRecovery = recoveries.find(r => r.id === updatedRecovery.id);
    if (!oldRecovery) return;

    setBills(prev => prev.map(b => {
      if (b.billNumber === updatedRecovery.billNumber) {
        const adjustedRecovery = b.recovery - oldRecovery.recoveryAmount + updatedRecovery.recoveryAmount;
        return { ...b, recovery: adjustedRecovery, balance: b.billAmount - adjustedRecovery };
      }
      return b;
    }));

    setRecoveries(prev => prev.map(r => r.id === updatedRecovery.id ? updatedRecovery : r));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery record? The bill balance will be updated.")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        setBills(prev => prev.map(b => {
          if (b.billNumber === rec.billNumber) {
            const totalRec = b.recovery - rec.recoveryAmount;
            return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
          }
          return b;
        }));
      }
      setRecoveries(prev => prev.filter(r => r.id !== id));
    }
  };

  const handleEditClick = (type: 'bill' | 'recovery' | 'customer' | 'ob', data: any) => {
    setEditingItem({ type, data });
    setActiveTab('edit');
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 text-slate-900">
      <nav className="w-full md:w-64 bg-slate-900 text-white flex-shrink-0 p-6 flex flex-col overflow-y-auto max-h-screen sticky top-0">
        <div className="flex items-center gap-2 mb-10">
          <div className="w-8 h-8 bg-blue-500 rounded-lg flex items-center justify-center font-bold text-white">B</div>
          <h1 className="text-xl font-bold tracking-tight">BillTrack Pro</h1>
        </div>

        <div className="space-y-1 flex-grow">
          <p className="text-[10px] uppercase font-bold text-slate-500 mb-2 px-4 tracking-widest">Main</p>
          <NavItem active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} label="Dashboard" icon={<DashIcon />} />
          <NavItem active={activeTab === 'today'} onClick={() => setActiveTab('today')} label="Today's Activity" icon={<TodayIcon />} />
          <NavItem active={activeTab === 'summary'} onClick={() => setActiveTab('summary')} label="OB Summary" icon={<ChartIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Operations</p>
          <NavItem active={activeTab === 'bills'} onClick={() => setActiveTab('bills')} label="Billing" icon={<PlusIcon />} />
          <NavItem active={activeTab === 'recovery'} onClick={() => setActiveTab('recovery')} label="Recovery" icon={<RecIcon />} />
          <NavItem active={activeTab === 'ledger'} onClick={() => setActiveTab('ledger')} label="Ledger" icon={<BookIcon />} />

          <p className="text-[10px] uppercase font-bold text-slate-500 mt-6 mb-2 px-4 tracking-widest">Master Data</p>
          <NavItem active={activeTab === 'customers'} onClick={() => setActiveTab('customers')} label="Customers" icon={<UserIcon />} />
          <NavItem active={activeTab === 'obs'} onClick={() => setActiveTab('obs')} label="Order Bookers" icon={<BriefcaseIcon />} />
          <NavItem active={activeTab === 'import'} onClick={() => setActiveTab('import')} label="Import Data" icon={<ImportIcon />} />

          {editingItem && (
            <div className="mt-4 pt-4 border-t border-slate-800">
               <NavItem active={activeTab === 'edit'} onClick={() => setActiveTab('edit')} label="Continue Editing" icon={<EditIcon />} />
            </div>
          )}
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-8 overflow-y-auto">
        <div className="max-w-6xl mx-auto">
          {activeTab === 'dashboard' && <Dashboard bills={bills} recoveries={recoveries} />}
          {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
          {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
          {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
          {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
          {activeTab === 'ledger' && (
            <Ledger 
              bills={bills} 
              recoveries={recoveries} 
              onEditBill={(b) => handleEditClick('bill', b)} 
              onDeleteBill={deleteBill}
              onEditRecovery={(r) => handleEditClick('recovery', r)}
              onDeleteRecovery={deleteRecovery}
            />
          )}
          {activeTab === 'customers' && (
            <CustomerForm 
              customers={customers} 
              setCustomers={setCustomers} 
              onEdit={(c) => handleEditClick('customer', c)}
            />
          )}
          {activeTab === 'obs' && (
            <OrderBookerForm 
              obs={obs} 
              setObs={setObs} 
              onEdit={(ob) => handleEditClick('ob', ob)}
            />
          )}
          {activeTab === 'import' && (
            <ImportPage 
              onImportBills={handleBulkImportBills} 
              onImportCustomers={handleBulkImportCustomers}
              customers={customers} 
              obs={obs} 
            />
          )}
          {activeTab === 'edit' && editingItem && (
            <EditEntryPage 
              item={editingItem} 
              customers={customers} 
              obs={obs}
              bills={bills}
              onUpdateBill={updateBill}
              onUpdateRecovery={updateRecovery}
              onUpdateCustomer={(c) => {
                setCustomers(prev => prev.map(item => item.id === c.id ? c : item));
                setEditingItem(null);
                setActiveTab('customers');
              }}
              onUpdateOB={(ob) => {
                setObs(prev => prev.map(item => item.id === ob.id ? ob : item));
                setEditingItem(null);
                setActiveTab('obs');
              }}
              onCancel={() => {
                setEditingItem(null);
                setActiveTab('ledger');
              }}
            />
          )}
        </div>
      </main>
    </div>
  );
};

const NavItem = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all ${active ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}>
