import React from 'react';
import { Bill, OrderBooker } from '../types';

interface Props {
  bills: Bill[];
  obs: OrderBooker[];
}

const Summary: React.FC<Props> = ({ bills, obs }) => {
  const summaryData = obs.map(ob => {
    const obBills = bills.filter(b => b.obCode === ob.code);
    const totalSales = obBills.reduce((s, b) => s + b.billAmount, 0);
    const totalBalance = obBills.reduce((s, b) => s + b.balance, 0);
    const totalRecovery = totalSales - totalBalance;
    const recoveryRate = totalSales ? Math.round((totalRecovery / totalSales) * 100) : 0;

    return {
      ...ob,
      totalSales,
      totalBalance,
      totalRecovery,
      recoveryRate
    };
  });

  const exportCSV = () => {
    let csvContent = "data:text/csv;charset=utf-8,";
    csvContent += "OB Code,OB Name,Total Billing,Total Recovery,Outstanding Balance,Recovery Rate(%)\n";
    summaryData.forEach(d => {
      csvContent += `${d.code},${d.name},${d.totalSales},${d.totalRecovery},${d.totalBalance},${d.recoveryRate}%\n`;
    });
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `OB_Performance_Summary_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-8 animate-fadeIn">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900 tracking-tighter">Credit Performance</h2>
          <p className="text-slate-500">Breakdown of recovery and outstanding balances by Order Booker.</p>
        </div>
        <div className="flex gap-2 print:hidden">
            <button onClick={exportCSV} className="px-5 py-2.5 bg-slate-100 text-slate-700 rounded-xl text-xs font-black uppercase hover:bg-slate-200 transition-all flex items-center gap-2">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                Export CSV
            </button>
            <button onClick={() => window.print()} className="px-5 py-2.5 bg-slate-900 text-white rounded-xl text-xs font-black uppercase hover:bg-slate-800 transition-all flex items-center gap-2 shadow-lg">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z" /></svg>
                Print Report
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {summaryData.map(data => (
          <div key={data.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-md transition-all">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h3 className="text-lg font-black text-slate-900 leading-none">{data.name}</h3>
                <span className="text-[10px] font-bold text-slate-400 tracking-widest uppercase">{data.code}</span>
              </div>
              <div className={`px-2 py-1 rounded-lg text-[10px] font-black ${data.recoveryRate > 70 ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                {data.recoveryRate}% RECOVERY
              </div>
            </div>

            <div className="space-y-4">
              <StatRow label="Total Billing" value={`$${data.totalSales.toLocaleString()}`} />
              <StatRow label="Total Recovery" value={`$${data.totalRecovery.toLocaleString()}`} color="text-emerald-600" />
              <div className="h-px bg-slate-50 w-full" />
              <StatRow label="Outstanding Balance" value={`$${data.totalBalance.toLocaleString()}`} color="text-rose-600" bold />
            </div>

            <div className="mt-6 w-full bg-slate-100 h-2 rounded-full overflow-hidden">
              <div className="bg-blue-600 h-full transition-all" style={{width: `${data.recoveryRate}%`}} />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

