                    <div className="relative z-10">
                        <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Total Collected Recovery</p>
                        <h4 className="text-3xl font-black text-emerald-600">${stats.credit.toLocaleString()}</h4>
                    </div>
                </div>
                <div className="bg-slate-900 p-8 rounded-[40px] shadow-xl shadow-slate-200 relative overflow-hidden group print:bg-slate-100 print:text-black">
                    <div className="relative z-10">
                        <p className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2 print:text-slate-500">Net Outstanding (Balance)</p>
                        <h4 className="text-3xl font-black text-white print:text-slate-900">${stats.balance.toLocaleString()}</h4>
                    </div>
                </div>
            </div>

            <div className="bg-white rounded-[40px] border border-slate-100 shadow-sm overflow-hidden print:border-none print:shadow-none">
