                  </td>
                  <td className="px-8 py-6 text-right">
                    <span className="text-lg font-bold text-emerald-600">
                      ${data.totalRecovery.toLocaleString()}
                    </span>
                  </td>
                  <td className="px-8 py-6 text-right">
                    <span className="text-xl font-black text-rose-600">
