import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger';

const generateId = () => {
  try {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      return crypto.randomUUID();
    }
  } catch (e) {}
  return Math.random().toString(36).substring(2, 15) + Date.now().toString(36);
};

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  useEffect(() => {
    try {
      const load = (key: string) => JSON.parse(localStorage.getItem(key) || '[]');
      setBills(load('bt_bills'));
      setRecoveries(load('bt_recoveries'));
      setCustomers(load('bt_customers'));
      setObs(load('bt_obs'));

      const user = localStorage.getItem('bt_user');
      if (user) setCurrentUser(JSON.parse(user));
    } catch (e) {
      console.warn("LocalStorage access denied or corrupted.", e);
    }
  }, []);

  useEffect(() => {
    try {
      localStorage.setItem('bt_bills', JSON.stringify(bills));
      localStorage.setItem('bt_recoveries', JSON.stringify(recoveries));
      localStorage.setItem('bt_customers', JSON.stringify(customers));
      localStorage.setItem('bt_obs', JSON.stringify(obs));
      if (currentUser) {
        localStorage.setItem('bt_user', JSON.stringify(currentUser));
      } else {
        localStorage.removeItem('bt_user');
      }
    } catch (e) {}
  }, [bills, recoveries, customers, obs, currentUser]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const newBill: Bill = { ...bill, id: generateId(), recovery: 0, balance: bill.billAmount };
    setBills(prev => [newBill, ...prev]);
    setActiveTab('ledger');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    const preparedBills = newBills.map(b => ({
      ...b, id: generateId(), recovery: 0, balance: b.billAmount
    }));
    setBills(prev => [...preparedBills, ...prev]);
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    const prepared = newCustomers.map(c => ({ ...c, id: generateId() }));
    setCustomers(prev => [...prev, ...prepared]);
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    const prepared = newOBs.map(ob => ({ ...ob, id: generateId() }));
    setObs(prev => [...prev, ...prepared]);
    setActiveTab('obs');
  };

  const updateBill = (updatedBill: Bill) => {
    setBills(prev => prev.map(b => b.id === updatedBill.id ? updatedBill : b));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const billToDelete = bills.find(b => b.id === id);
      if (billToDelete) {
        setRecoveries(prev => prev.filter(r => r.billNumber !== billToDelete.billNumber));
      }
      setBills(prev => prev.filter(b => b.id !== id));
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const newRecovery: Recovery = { ...recovery, id: generateId() };
    setBills(prev => prev.map(b => {
      if (b.billNumber === recovery.billNumber) {
        const totalRec = b.recovery + recovery.recoveryAmount;
        return { ...b, recovery: totalRec, balance: b.billAmount - totalRec };
      }
      return b;
    }));
    setRecoveries(prev => [newRecovery, ...prev]);
    setActiveTab('ledger');
  };

  const updateRecovery = (updatedRecovery: Recovery) => {
    const oldRecovery = recoveries.find(r => r.id === updatedRecovery.id);
    if (!oldRecovery) return;

    setBills(prev => prev.map(b => {
      if (b.billNumber === updatedRecovery.billNumber) {
        const adjustedRecovery = b.recovery - oldRecovery.recoveryAmount + updatedRecovery.recoveryAmount;
        return { ...b, recovery: adjustedRecovery, balance: b.billAmount - adjustedRecovery };
      }
      return b;
    }));
    setRecoveries(prev => prev.map(r => r.id === updatedRecovery.id ? updatedRecovery : r));
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const recToDelete = recoveries.find(r => r.id === id);
      if (recToDelete) {
        setBills(prev => prev.map(b => {
          if (b.billNumber === recToDelete.billNumber) {
            const adjustedRecovery = b.recovery - recToDelete.recoveryAmount;
            return { ...b, recovery: adjustedRecovery, balance: b.billAmount - adjustedRecovery };
          }
          return b;
        }));
      }
      setRecoveries(prev => prev.filter(r => r.id !== id));
    }
  };

  const updateCustomer = (updated: Customer) => {
    setCustomers(prev => prev.map(c => c.id === updated.id ? updated : c));
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    setObs(prev => prev.map(o => o.id === updated.id ? updated : o));
    setEditingItem(null);
    setActiveTab('obs');
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button 
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
    >
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (!currentUser) {
    return <LoginPage onLogin={handleLogin} />;
  }

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans text-slate-900">
      {/* Sidebar Navigation */}
      <aside className="w-80 bg-white border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto">
        <div className="px-2">
          <h1 className="text-2xl font-black tracking-tighter text-slate-900 flex items-center gap-2">
            <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center text-white text-xs">BT</div>
            BillTrack <span className="text-blue-600">Pro</span>
          </h1>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Enterprise Ledger System</p>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-300 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-300 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-300 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-300 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
              <NavItem id="summary" label="Credit Summary" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="ob-ledger" label="OB Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>} />
              <NavItem id="customer-ledger" label="Customer Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 14v3m4-3v3m4-3v3M3 21h18M3 10h18M3 7l9-4 9 4M4 10h16v11H4V10z" /></svg>} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100 space-y-4">
           <div className="bg-slate-900 rounded-2xl p-4 text-white flex items-center gap-3">
              <div className="w-10 h-10 rounded-full bg-blue-600 flex items-center justify-center font-bold">
                {currentUser.name.charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold truncate max-w-[120px]">{currentUser.name}</p>
                <p className="text-[10px] text-slate-400 uppercase font-black">{currentUser.role}</p>
              </div>
           </div>
           <button 
             onClick={handleLogout}
             className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold text-rose-500 hover:bg-rose-50 transition-all text-xs uppercase"
           >
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             Logout Session
           </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (
          isAdmin ? 
          <Dashboard bills={bills} recoveries={recoveries} /> : 
          <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} />
        )}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}

        {isAdmin && (
          <>
            {activeTab === 'ledger' && (
              <Ledger 
                bills={bills} 
                recoveries={recoveries} 
                onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }}
                onDeleteBill={deleteBill}
                onEditRecovery={(r) => { setEditingItem({ type: 'recovery', data: r }); setActiveTab('edit'); }}
                onDeleteRecovery={deleteRecovery}
              />
            )}
            {activeTab === 'customers' && (
              <CustomerForm 
                customers={customers} 
                setCustomers={setCustomers} 
                obs={obs} 
                onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }}
              />
            )}
            {activeTab === 'obs' && (
              <OrderBookerForm 
                obs={obs} 
                setObs={setObs} 
                onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }}
              />
            )}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
            {activeTab === 'import' && (
              <ImportPage 
                onImportBills={handleBulkImportBills} 
                onImportCustomers={handleBulkImportCustomers} 
                onImportOBs={handleBulkImportOBs} 
                customers={customers} 
                obs={obs} 
              />
            )}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} />}
          </>
        )}

        {activeTab === 'edit' && editingItem && (
          <EditEntryPage 
            item={editingItem} 
            customers={customers} 
            obs={obs} 
            bills={bills}
            onUpdateBill={updateBill}
            onUpdateRecovery={updateRecovery}
            onUpdateCustomer={updateCustomer}
            onUpdateOB={updateOB}
            onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }}
          />
        )}
      </main>
    </div>
  );
};

export default App;

