import initSqlJs from 'https://esm.sh/sql.js@1.12.0';

let db: any = null;
const DB_NAME = 'billtrack_pro_db';
const STORE_NAME = 'sqlite_file';

// Initialize the database
export const initDB = async () => {
  try {
    const SQL = await initSqlJs({
      // Use a reliable, version-pinned CDN for the WASM file
      locateFile: file => `https://cdn.jsdelivr.net/npm/sql.js@1.12.0/dist/${file}`
    });

    // Try to load existing database from IndexedDB
    const savedData = await loadFromIndexedDB();

    if (savedData && savedData.byteLength > 0) {
      db = new SQL.Database(new Uint8Array(savedData));
    } else {
      db = new SQL.Database();
      createSchema();
    }
    return db;
  } catch (error) {
    console.error("Failed to initialize SQLite:", error);
    throw error;
  }
};

const createSchema = () => {
  if (!db) return;
  db.run(`
    CREATE TABLE IF NOT EXISTS customers (
      id TEXT PRIMARY KEY,
      code TEXT UNIQUE,
      name TEXT,
      address TEXT,
      obCode TEXT
    );

    CREATE TABLE IF NOT EXISTS obs (
      id TEXT PRIMARY KEY,
      code TEXT UNIQUE,
      name TEXT,
      phone TEXT
    );

    CREATE TABLE IF NOT EXISTS bills (
      id TEXT PRIMARY KEY,
      date TEXT,
      customerCode TEXT,
      obCode TEXT,
      billNumber TEXT UNIQUE,
      shopName TEXT,
      shopAddress TEXT,
      billType TEXT,
      billAmount REAL,
      recovery REAL,
      balance REAL
    );

    CREATE TABLE IF NOT EXISTS recoveries (
      id TEXT PRIMARY KEY,
      billNumber TEXT,
      billDate TEXT,
      recoveryDate TEXT,
      type TEXT,
      billAmountAtRecovery REAL,
      recoveryAmount REAL,
      remainingAmount REAL,
      FOREIGN KEY(billNumber) REFERENCES bills(billNumber) ON DELETE CASCADE
    );
  `);
  persist();
};

// Persistence logic using IndexedDB
const persist = async () => {
  if (!db) return;
  try {
    const binaryArray = db.export();
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const dbInstance = request.result;
      if (!dbInstance.objectStoreNames.contains(STORE_NAME)) {
        dbInstance.createObjectStore(STORE_NAME);
      }
    };

    request.onsuccess = () => {
      const idb = request.result;
      try {
        const transaction = idb.transaction(STORE_NAME, 'readwrite');
        transaction.objectStore(STORE_NAME).put(binaryArray, 'current');
      } catch (e) {
        console.warn("Failed to save to IndexedDB. Browser might be in private mode.", e);
      }
    };
  } catch (e) {
    console.error("Critical error in database persistence:", e);
  }
};

const loadFromIndexedDB = (): Promise<ArrayBuffer | null> => {
  return new Promise((resolve) => {
    try {
      const request = indexedDB.open(DB_NAME, 1);

      request.onupgradeneeded = () => {
        const dbInstance = request.result;
        if (!dbInstance.objectStoreNames.contains(STORE_NAME)) {
          dbInstance.createObjectStore(STORE_NAME);
        }
        resolve(null);
      };

      request.onsuccess = () => {
        const idb = request.result;
        if (!idb.objectStoreNames.contains(STORE_NAME)) {
          resolve(null);
          return;
        }
        const transaction = idb.transaction(STORE_NAME, 'readonly');
        const getRequest = transaction.objectStore(STORE_NAME).get('current');
        getRequest.onsuccess = () => resolve(getRequest.result || null);
        getRequest.onerror = () => resolve(null);
      };

      request.onerror = () => {
        console.warn("IndexedDB access denied. Data will not persist between sessions.");
        resolve(null);
      };
    } catch (e) {
      resolve(null);
    }
  });
};

// Query wrappers
export const executeQuery = (sql: string, params: any[] = []) => {
  if (!db) {
    console.warn("Attempted query before DB initialization.");
    return [];
  }
  try {
    const stmt = db.prepare(sql);
    stmt.bind(params);
    const results = [];
    while (stmt.step()) {
      results.push(stmt.getAsObject());
    }
    stmt.free();
    return results;
  } catch (e) {
    console.error(`Query Error: ${sql}`, e);
    return [];
  }
};

export const runCommand = (sql: string, params: any[] = []) => {
  if (!db) {
    console.warn("Attempted command before DB initialization.");
    return;
  }
  try {
    db.run(sql, params);
    persist();
  } catch (e) {
    console.error(`Command Error: ${sql}`, e);
    throw e;
  }
};

export const getDatabaseFile = () => {
  return db ? db.export() : null;
};

export const resetDatabase = async () => {
  const request = indexedDB.deleteDatabase(DB_NAME);
  request.onsuccess = () => window.location.reload();
  request.onerror = () => alert("Could not clear database.");
};

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType } from './types';
