import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();
        setIsDbReady(true);
        refreshData();

        const savedTheme = localStorage.getItem('bt_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const user = localStorage.getItem('bt_user');
        if (user) setCurrentUser(JSON.parse(user));
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  useEffect(() => {
    localStorage.setItem('bt_theme', theme);
    if (currentUser) {
      localStorage.setItem('bt_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('bt_user');
    }
  }, [currentUser, theme]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    setActiveTab('ledger');
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) {
        runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      }
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    // Update bill balance
    runCommand(`
      UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?
    `, [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`
          UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?
        `, [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      const id = generateId();
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [id, b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button 
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
    >
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  // Fallback UI for Database Errors
  if (dbError) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
        <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
          <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
          <p className="text-slate-500 mb-4">{dbError}</p>
          <p className="text-xs text-slate-400 mb-8 leading-relaxed">This typically happens if WASM support is disabled or if the SQLite binaries could not be fetched. Check your console for more details.</p>
          <div className="flex flex-col gap-3">
            <button 
              onClick={() => window.location.reload()}
              className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg"
            >
              Retry Booting
            </button>
            <button 
              onClick={resetDatabase}
              className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all"
            >
              Wipe Local Data & Reset
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
            </div>
          </div>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />
              <NavItem id="themes" label="Appearance" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
              <NavItem id="summary" label="Credit Summary" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="ob-ledger" label="OB Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>} />
              <NavItem id="customer-ledger" label="Customer Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 14v3m4-3v3m4-3v3M3 21h18M3 10h18M3 7l9-4 9 4M4 10h16v11H4V10z" /></svg>} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100/10 space-y-4">
           <div className={`rounded-2xl p-4 flex items-center gap-3 ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/5 text-white' : 'bg-slate-900 text-white'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${getThemeColor()}`}>
                {currentUser.name.charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold truncate max-w-[120px]">{currentUser.name}</p>
                <p className="text-[10px] text-slate-500 uppercase font-black">{currentUser.role}</p>
              </div>
           </div>
           <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold text-rose-500 hover:bg-rose-500/10 transition-all text-xs uppercase">
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             Logout Session
           </button>
        </div>
      </aside>

      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (isAdmin ? <Dashboard bills={bills} recoveries={recoveries} /> : <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} />)}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
        {isAdmin && (
          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} setCustomers={() => {}} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} setObs={() => {}} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
            {activeTab === 'import' && <ImportPage onImportBills={handleBulkImportBills} onImportCustomers={handleBulkImportCustomers} onImportOBs={handleBulkImportOBs} customers={customers} obs={obs} />}
            {activeTab === 'themes' && <ThemePage currentTheme={theme} onThemeChange={setTheme} />}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage item={editingItem} customers={customers} obs={obs} bills={bills} onUpdateBill={updateBill} onUpdateRecovery={() => {}} onUpdateCustomer={updateCustomer} onUpdateOB={updateOB} onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} />
        )}
      </main>
    </div>
  );
};

export default App;

/**
 * database.ts
 * Relational SQLite persistence layer for BillTrack Pro.
 * Uses sql.js (WASM) and IndexedDB for permanent browser-side storage.
 */

let db: any = null;
let SQL_LIB: any = null;
const DB_NAME = 'billtrack_pro_db_v1';
const STORE_NAME = 'sqlite_file';

/**
 * Loads the SQL.js library via a script tag to avoid ESM/Node polyfill issues.
 */
const loadSqlLibrary = (): Promise<any> => {
  return new Promise((resolve, reject) => {
    if ((window as any).initSqlJs) {
      resolve((window as any).initSqlJs);
      return;
    }
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/sql.js@1.12.0/dist/sql-wasm.js';
    script.async = true;
    script.onload = () => resolve((window as any).initSqlJs);
    script.onerror = () => reject(new Error("Failed to load SQL.js script from CDN. Check your internet connection."));
    document.head.appendChild(script);
  });
};

/**
 * Initializes the SQLite database. 
 */
export const initDB = async () => {
  try {
    const initSqlJs = await loadSqlLibrary();
    const wasmResponse = await fetch('https://cdn.jsdelivr.net/npm/sql.js@1.12.0/dist/sql-wasm.wasm');
    if (!wasmResponse.ok) throw new Error("Could not fetch SQLite WASM binary.");
    const wasmBinary = await wasmResponse.arrayBuffer();

    SQL_LIB = await initSqlJs({ wasmBinary });
    const savedData = await loadFromIndexedDB();

    if (savedData && savedData.byteLength > 0) {
      db = new SQL_LIB.Database(new Uint8Array(savedData));
    } else {
      db = new SQL_LIB.Database();
      createSchema();
    }
    return db;
  } catch (error) {
    console.error("Database initialization error:", error);
    throw error;
  }
};

const createSchema = () => {
  if (!db) return;
  db.run(`
    CREATE TABLE IF NOT EXISTS settings (
      key TEXT PRIMARY KEY,
      value TEXT
    );

    CREATE TABLE IF NOT EXISTS customers (
      id TEXT PRIMARY KEY,
      code TEXT UNIQUE,
      name TEXT,
      address TEXT,
      obCode TEXT
    );

    CREATE TABLE IF NOT EXISTS obs (
      id TEXT PRIMARY KEY,
      code TEXT UNIQUE,
      name TEXT,
      phone TEXT
    );

    CREATE TABLE IF NOT EXISTS bills (
      id TEXT PRIMARY KEY,
      date TEXT,
      customerCode TEXT,
      obCode TEXT,
      billNumber TEXT UNIQUE,
      shopName TEXT,
      shopAddress TEXT,
      billType TEXT,
      billAmount REAL,
      recovery REAL,
      balance REAL
    );

    CREATE TABLE IF NOT EXISTS recoveries (
      id TEXT PRIMARY KEY,
      billNumber TEXT,
      billDate TEXT,
      recoveryDate TEXT,
      type TEXT,
      billAmountAtRecovery REAL,
      recoveryAmount REAL,
      remainingAmount REAL,
      FOREIGN KEY(billNumber) REFERENCES bills(billNumber) ON DELETE CASCADE
    );
  `);
  persist();
};

/**
 * Database Settings Helpers
 */
export const getSetting = (key: string): string | null => {
  const result = executeQuery("SELECT value FROM settings WHERE key = ?", [key]);
  return result.length > 0 ? (result[0] as any).value : null;
};

export const setSetting = (key: string, value: string) => {
  runCommand("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", [key, value]);
};

/**
 * Saves binary state to IndexedDB.
 */
const persist = async () => {
  if (!db) return;
  try {
    const binaryArray = db.export();
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const idb = request.result;
      if (!idb.objectStoreNames.contains(STORE_NAME)) {
        idb.createObjectStore(STORE_NAME);
      }
    };

    request.onsuccess = () => {
      const idb = request.result;
      try {
        const transaction = idb.transaction(STORE_NAME, 'readwrite');
        transaction.objectStore(STORE_NAME).put(binaryArray, 'current');
      } catch (e) {
        console.warn("IndexedDB Write Error:", e);
      }
    };
  } catch (e) {
    console.error("Persistence failed:", e);
  }
};

const loadFromIndexedDB = (): Promise<ArrayBuffer | null> => {
  return new Promise((resolve) => {
    try {
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => {
        const idb = request.result;
        if (!idb.objectStoreNames.contains(STORE_NAME)) idb.createObjectStore(STORE_NAME);
        resolve(null);
      };
      request.onsuccess = () => {
        const idb = request.result;
        if (!idb.objectStoreNames.contains(STORE_NAME)) { resolve(null); return; }
        const transaction = idb.transaction(STORE_NAME, 'readonly');
        const getRequest = transaction.objectStore(STORE_NAME).get('current');
        getRequest.onsuccess = () => resolve(getRequest.result || null);
        getRequest.onerror = () => resolve(null);
      };
      request.onerror = () => resolve(null);
    } catch (e) { resolve(null); }
  });
};

export const executeQuery = (sql: string, params: any[] = []) => {
  if (!db) return [];
  try {
    const stmt = db.prepare(sql);
    stmt.bind(params);
    const results = [];
    while (stmt.step()) results.push(stmt.getAsObject());
    stmt.free();
    return results;
  } catch (e) {
    console.error(`SQL Select Error: ${sql}`, e);
    return [];
  }
};

export const runCommand = (sql: string, params: any[] = []) => {
  if (!db) return;
  try {
    db.run(sql, params);
    persist();
  } catch (e) {
    console.error(`SQL Write Error: ${sql}`, e);
    throw e;
  }
};

export const getDatabaseFile = () => db ? db.export() : null;

export const resetDatabase = async () => {
  const request = indexedDB.deleteDatabase(DB_NAME);
  request.onsuccess = () => window.location.reload();
  request.onerror = () => alert("Reset failed.");
};

