              </div>
            </div>

            {/* Amount Input & Quick Selects */}
            <div className={`transition-all ${selectedBill ? 'opacity-100' : 'opacity-20 pointer-events-none'}`}>
              <div className="flex justify-between items-end mb-2 ml-1">
