type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) setCurrentUser(JSON.parse(savedUserJson));

        setIsDbReady(true);
        refreshData();
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry Booting</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Wipe & Reset Database</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
            </div>
          </div>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />
              <NavItem id="themes" label="Appearance" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
              <NavItem id="summary" label="Credit Summary" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="ob-ledger" label="OB Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>} />
              <NavItem id="customer-ledger" label="Customer Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 14v3m4-3v3m4-3v3M3 21h18M3 10h18M3 7l9-4 9 4M4 10h16v11H4V10z" /></svg>} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100/10 space-y-4">
           <div className={`rounded-2xl p-4 flex items-center gap-3 ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/5 text-white' : 'bg-slate-900 text-white'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${getThemeColor()}`}>
                {currentUser.name.charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold truncate max-w-[120px]">{currentUser.name}</p>
                <p className="text-[10px] text-slate-500 uppercase font-black">{currentUser.role}</p>
              </div>
           </div>
           <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold text-rose-500 hover:bg-rose-500/10 transition-all text-xs uppercase">
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             Logout Session
           </button>
        </div>
      </aside>

      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (isAdmin ? <Dashboard bills={bills} recoveries={recoveries} /> : <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} />)}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} />}
        {isAdmin && (
          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} setCustomers={() => {}} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} setObs={() => {}} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} />}
            {activeTab === 'import' && <ImportPage onImportBills={handleBulkImportBills} onImportCustomers={handleBulkImportCustomers} onImportOBs={handleBulkImportOBs} customers={customers} obs={obs} />}
            {activeTab === 'themes' && <ThemePage currentTheme={theme} onThemeChange={handleThemeChange} />}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage item={editingItem} customers={customers} obs={obs} bills={bills} onUpdateBill={updateBill} onUpdateRecovery={() => {}} onUpdateCustomer={updateCustomer} onUpdateOB={updateOB} onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) setCurrentUser(JSON.parse(savedUserJson));

        setIsDbReady(true);
        refreshData();
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleCurrencyChange = (newSymbol: string) => {
    setCurrencySymbol(newSymbol);
    setSetting('app_currency', newSymbol);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry Booting</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Wipe & Reset Database</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
            </div>
          </div>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />
              <NavItem id="themes" label="Appearance" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
              <NavItem id="summary" label="Credit Summary" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="ob-ledger" label="OB Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>} />
              <NavItem id="customer-ledger" label="Customer Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 14v3m4-3v3m4-3v3M3 21h18M3 10h18M3 7l9-4 9 4M4 10h16v11H4V10z" /></svg>} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100/10 space-y-4">
           <div className={`rounded-2xl p-4 flex items-center gap-3 ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/5 text-white' : 'bg-slate-900 text-white'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${getThemeColor()}`}>
                {currentUser.name.charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold truncate max-w-[120px]">{currentUser.name}</p>
                <p className="text-[10px] text-slate-500 uppercase font-black">{currentUser.role}</p>
              </div>
           </div>
           <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold text-rose-500 hover:bg-rose-500/10 transition-all text-xs uppercase">
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             Logout Session
           </button>
        </div>
      </aside>

      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (isAdmin ? <Dashboard bills={bills} recoveries={recoveries} currency={currencySymbol} /> : <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} currency={currencySymbol} />)}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} currency={currencySymbol} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} currency={currencySymbol} />}
        {isAdmin && (
          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} currency={currencySymbol} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} setCustomers={() => {}} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} setObs={() => {}} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} currency={currencySymbol} />}
            {activeTab === 'import' && <ImportPage onImportBills={handleBulkImportBills} onImportCustomers={handleBulkImportCustomers} onImportOBs={handleBulkImportOBs} customers={customers} obs={obs} currency={currencySymbol} />}
            {activeTab === 'themes' && <ThemePage currentTheme={theme} currentCurrency={currencySymbol} onThemeChange={handleThemeChange} onCurrencyChange={handleCurrencyChange} />}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} currency={currencySymbol} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage item={editingItem} customers={customers} obs={obs} bills={bills} currency={currencySymbol} onUpdateBill={updateBill} onUpdateRecovery={() => {}} onUpdateCustomer={updateCustomer} onUpdateOB={updateOB} onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} />
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { ThemeType, ThemeConfig } from '../types';
import { getDatabaseFile } from '../database';

interface ThemePageProps {
  currentTheme: ThemeType;
  currentCurrency: string;
  onThemeChange: (theme: ThemeType) => void;
  onCurrencyChange: (currency: string) => void;
}

const themes: ThemeConfig[] = [
  { id: 'blue', name: 'Enterprise Blue', primary: 'bg-blue-600', secondary: 'bg-blue-50', accent: 'text-blue-600', sidebar: 'bg-white' },
  { id: 'indigo', name: 'Midnight Indigo', primary: 'bg-indigo-600', secondary: 'bg-indigo-50', accent: 'text-indigo-600', sidebar: 'bg-slate-900' },
  { id: 'emerald', name: 'Emerald Growth', primary: 'bg-emerald-600', secondary: 'bg-emerald-50', accent: 'text-emerald-600', sidebar: 'bg-white' },
  { id: 'crimson', name: 'Crimson Ledger', primary: 'bg-rose-600', secondary: 'bg-rose-50', accent: 'text-rose-600', sidebar: 'bg-slate-900' },
  { id: 'amber', name: 'Amber Gold', primary: 'bg-amber-500', secondary: 'bg-amber-50', accent: 'text-amber-600', sidebar: 'bg-white' },
  { id: 'slate', name: 'Modern Slate', primary: 'bg-slate-900', secondary: 'bg-slate-100', accent: 'text-slate-900', sidebar: 'bg-white' },
];

const currencies = [
  { symbol: 'Rs.', name: 'PKR / INR' },
  { symbol: '$', name: 'USD / CAD / AUD' },
  { symbol: '€', name: 'Euro' },
  { symbol: '£', name: 'GBP' },
  { symbol: '₹', name: 'INR (Modern)' },
  { symbol: 'د.إ', name: 'AED' },
  { symbol: '﷼', name: 'SAR' },
  { symbol: '¥', name: 'JPY / CNY' },
];

const ThemePage: React.FC<ThemePageProps> = ({ currentTheme, currentCurrency, onThemeChange, onCurrencyChange }) => {
  const downloadDatabase = () => {
    const data = getDatabaseFile();
    if (!data) return;
    const blob = new Blob([data], { type: 'application/x-sqlite3' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `billtrack_pro_${new Date().toISOString().split('T')[0]}.sqlite`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-12 animate-fadeIn">
      <div className="max-w-3xl">
        <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Appearance & Settings</h2>
        <p className="text-slate-500 mt-2 text-lg font-medium leading-relaxed">
          Customize the look and feel of your enterprise ledger. Choose a workspace theme and local currency that fits your operational style.
        </p>
      </div>

      <section>
        <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Workspace Theme</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {themes.map((theme) => (
            <button
              key={theme.id}
              onClick={() => onThemeChange(theme.id)}
              className={`group relative text-left bg-white rounded-[48px] border-4 p-2 transition-all duration-500 hover:shadow-2xl hover:scale-[1.02] ${
                currentTheme === theme.id ? 'border-blue-500 shadow-xl' : 'border-transparent shadow-sm'
              }`}
            >
              <div className={`rounded-[40px] p-8 ${theme.id === 'slate' ? 'bg-slate-50' : theme.secondary} h-full`}>
                <div className="flex items-center justify-between mb-8">
                  <div className={`w-12 h-12 ${theme.primary} rounded-2xl shadow-lg shadow-black/5 flex items-center justify-center text-white font-bold`}>
                    Aa
                  </div>
                  {currentTheme === theme.id && (
                    <span className="bg-blue-500 text-white text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full shadow-lg">Active</span>
                  )}
                </div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight mb-2">{theme.name}</h3>
                <div className="space-y-3 mt-6">
                  <div className="h-4 w-full bg-white rounded-lg shadow-sm"></div>
                  <div className="flex gap-2">
                    <div className={`h-8 w-1/2 ${theme.primary} rounded-xl shadow-md`}></div>
                    <div className="h-8 w-1/2 bg-white rounded-xl shadow-sm"></div>
                  </div>
                </div>
              </div>
            </button>
          ))}
        </div>
      </section>

      <section>
        <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Currency Preference</h3>
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-8 gap-4">
          {currencies.map((curr) => (
            <button
              key={curr.symbol}
              onClick={() => onCurrencyChange(curr.symbol)}
              className={`p-6 rounded-[32px] border-2 transition-all flex flex-col items-center gap-2 group ${
                currentCurrency === curr.symbol 
                  ? 'border-blue-500 bg-blue-50 shadow-md' 
                  : 'border-slate-100 bg-white hover:border-slate-300'
              }`}
            >
              <span className={`text-2xl font-black ${currentCurrency === curr.symbol ? 'text-blue-600' : 'text-slate-400'}`}>
                {curr.symbol}
              </span>
              <span className="text-[8px] font-black uppercase text-slate-400 text-center tracking-tighter">
                {curr.name}
              </span>
            </button>
          ))}
        </div>
      </section>

      <div className="bg-slate-900 p-12 rounded-[56px] text-white flex flex-col md:flex-row items-center gap-10">
         <div className="flex-1 space-y-4">
            <h3 className="text-3xl font-black tracking-tight flex items-center gap-4">
              <svg className="w-8 h-8 text-emerald-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 7v10c0 2.21 3.582 4 8 4s8-1.79 8-4V7M4 7c0 2.21 3.582 4 8 4s8-1.79 8-4M4 7c0-2.21 3.582-4 8-4s8 1.79 8 4m0 5c0 2.21-3.582 4-8 4s-8-1.79-8-4" /></svg>
              SQLite Database Management
            </h3>
            <p className="text-slate-400 font-medium leading-relaxed">Your data is stored in an industry-standard SQLite relational database within your browser. You can export the database file to keep a secure offline backup or for advanced reporting.</p>
         </div>
         <div className="w-full md:w-auto">
            <button 
              onClick={downloadDatabase}
              className="w-full md:w-auto px-8 py-5 bg-white text-slate-900 rounded-[24px] font-black text-lg hover:bg-slate-100 transition-all flex items-center justify-center gap-3 shadow-xl"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              EXPORT .SQLITE
            </button>
         </div>
      </div>
    </div>
  );
};

export default ThemePage;

import React from 'react';
import { Bill, Recovery } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface DashboardProps {
  bills: Bill[];
  recoveries: Recovery[];
  currency: string;
}

const Dashboard: React.FC<DashboardProps> = ({ bills, recoveries, currency }) => {
  const totalSales = bills.reduce((sum, b) => sum + b.billAmount, 0);
  const totalRecovery = recoveries.reduce((sum, r) => sum + r.recoveryAmount, 0);
  const totalOutstanding = totalSales - totalRecovery;

  const chartData = bills.slice(0, 7).reverse().map(b => ({
    name: b.billNumber,
    amount: b.billAmount,
    recovery: b.recovery,
    balance: b.balance
  }));

  const pieData = [
    { name: 'Recovered', value: totalRecovery, color: '#3b82f6' },
    { name: 'Outstanding', value: totalOutstanding, color: '#f43f5e' }
  ];

  return (
    <div className="space-y-6 animate-fadeIn">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-extrabold text-slate-900 tracking-tight">Insights Overview</h2>
          <p className="text-slate-500 mt-1">Real-time performance tracking for all shop accounts.</p>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
          label="Total Billing" 
          value={`${currency} ${totalSales.toLocaleString()}`} 
          color="blue"
          icon={<BillingIcon />}
        />
        <StatCard 
          label="Total Recovery" 
          value={`${currency} ${totalRecovery.toLocaleString()}`} 
          color="emerald" 
          icon={<RecoveryIcon />}
        />
        <StatCard 
          label="Total Outstanding" 
          value={`${currency} ${totalOutstanding.toLocaleString()}`} 
          color="rose"
          icon={<AlertIcon />}
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Trend Chart */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold mb-6 flex items-center gap-2">
            <span className="w-1 h-6 bg-blue-500 rounded-full"></span>
            Recent Billing Trend
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 12}} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}} 
                  contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)'}}
                  formatter={(value: any) => [`${currency} ${value.toLocaleString()}`, '']}
                />
                <Bar dataKey="amount" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Bill Amount" />
                <Bar dataKey="recovery" fill="#10b981" radius={[4, 4, 0, 0]} name="Recovery" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Recovery Breakdown */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col items-center">
          <h3 className="text-lg font-bold mb-6 self-start flex items-center gap-2">
            <span className="w-1 h-6 bg-rose-500 rounded-full"></span>
            Recovery Status
          </h3>
          <div className="h-[250px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={pieData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {pieData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip formatter={(value: any) => `${currency} ${value.toLocaleString()}`} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex gap-8 mt-4">
            {pieData.map(d => (
              <div key={d.name} className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full" style={{backgroundColor: d.color}}></div>
                <span className="text-sm font-medium text-slate-600">{d.name}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

const StatCard: React.FC<{ label: string; value: string; color: 'blue' | 'emerald' | 'rose'; icon: React.ReactNode }> = ({ label, value, color, icon }) => {
