import React, { useState, useEffect } from 'react';
import { BillType, Bill, Customer, OrderBooker } from '../types';

interface BillFormProps {
  customers: Customer[];
  obs: OrderBooker[];
  onSubmit: (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage?: boolean) => void;
  currency: string;
}

const BillForm: React.FC<BillFormProps> = ({ customers, obs, onSubmit, currency }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    customerCode: '',
    obCode: '',
    billNumber: '',
    shopName: '',
    shopAddress: '',
    billType: BillType.FOOD,
    billAmount: ''
  });

  // Auto-fill logic for shop details based on customer code
  useEffect(() => {
    const customer = customers.find(c => c.code.toLowerCase() === formData.customerCode.toLowerCase());
    if (customer) {
      setFormData(prev => ({
        ...prev,
        shopName: customer.name,
        shopAddress: customer.address,
        obCode: customer.obCode || prev.obCode // Use default OB from customer if available
      }));
    }
  }, [formData.customerCode, customers]);

  const handleReset = () => {
    if (window.confirm("Clear all fields and start a new bill?")) {
      setFormData({
        date: new Date().toISOString().split('T')[0],
        customerCode: '',
        obCode: '',
        billNumber: '',
        shopName: '',
        shopAddress: '',
        billType: BillType.FOOD,
        billAmount: ''
      });
    }
  };

  const handleFormSubmit = (e: React.FormEvent, stayOnPage: boolean = false) => {
    e.preventDefault();
    if (!formData.billAmount || isNaN(Number(formData.billAmount))) return;
    if (!formData.billNumber.trim()) {
      alert("Please enter a Bill Number");
      return;
    }

    onSubmit({ ...formData, billAmount: Number(formData.billAmount) }, stayOnPage);

    // Reset form for next entry
    setFormData({
      date: new Date().toISOString().split('T')[0],
      customerCode: '',
      obCode: '',
      billNumber: '',
      shopName: '',
      shopAddress: '',
      billType: BillType.FOOD,
      billAmount: ''
    });
  };

  return (
    <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-100 max-w-5xl mx-auto animate-slideUp">
      <div className="flex justify-between items-start mb-10 border-b border-slate-50 pb-8">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter">New Billing Entry</h2>
          <p className="text-slate-500 mt-2 font-medium">Organize your records by filling in transaction and customer details.</p>
        </div>
        <button 
          type="button" 
          onClick={handleReset}
          className="flex items-center gap-2 px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-2xl text-xs font-black uppercase transition-all shadow-sm active:scale-95"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Quick New
        </button>
      </div>

      <form onSubmit={(e) => handleFormSubmit(e, false)} className="space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">

          {/* Column 1: Transaction Details */}
          <div className="space-y-6">
            <SectionHeader title="Transaction Details" icon={<BillIcon />} />

            <FormGroup label="Bill Date">
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="input-base" required />
            </FormGroup>

            <FormGroup label="Bill Number">
              <input 
                type="text" 
                placeholder="Enter Bill #"
                value={formData.billNumber} 
                onChange={e => setFormData({...formData, billNumber: e.target.value})} 
                className="input-base font-bold text-slate-900" 
                required
              />
            </FormGroup>

            <FormGroup label="Bill Type">
              <select value={formData.billType} onChange={e => setFormData({...formData, billType: e.target.value as BillType})} className="input-base font-bold text-slate-900">
                {Object.values(BillType).map(type => <option key={type} value={type}>{type}</option>)}
              </select>
            </FormGroup>

            <FormGroup label={`Bill Amount (${currency})`}>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">{currency}</span>
                <input 
                  type="number" 
                  placeholder="0" 
                  value={formData.billAmount} 
                  onChange={e => setFormData({...formData, billAmount: e.target.value})} 
                  className={`input-base font-black text-2xl text-blue-600 ${currency.length > 1 ? 'pl-14' : 'pl-10'}`} 
                  required 
                />
              </div>
            </FormGroup>
          </div>

          {/* Column 2: Customer & Shop Info */}
          <div className="space-y-6">
            <SectionHeader title="Customer Information" icon={<ShopIcon />} />

            <FormGroup label="Customer Code">
              <div className="relative">
                <input 
                  type="text" 
                  placeholder="e.g. C001"
                  value={formData.customerCode} 
                  onChange={e => setFormData({...formData, customerCode: e.target.value})}
                  className={`input-base uppercase ${customers.some(c => c.code.toLowerCase() === formData.customerCode.toLowerCase()) ? 'border-emerald-500 ring-emerald-100 ring-4' : ''}`}
                  required
                />
                {customers.some(c => c.code.toLowerCase() === formData.customerCode.toLowerCase()) && (
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 bg-emerald-100 text-emerald-600 text-[10px] px-2 py-1 rounded-lg font-black tracking-widest uppercase">Matched</span>
                )}
              </div>
            </FormGroup>

            <FormGroup label="Order Booker (OB)">
              <select 
                value={formData.obCode} 
                onChange={e => setFormData({...formData, obCode: e.target.value})}
                className="input-base"
                required
              >
                <option value="">Select OB</option>
                {obs.map(ob => (
                  <option key={ob.id} value={ob.code}>{ob.name} ({ob.code})</option>
                ))}
              </select>
            </FormGroup>

            <FormGroup label="Shop Name">
              <input 
                type="text" 
                placeholder="Shop Name"
                value={formData.shopName} 
                onChange={e => setFormData({...formData, shopName: e.target.value})} 
                className="input-base" 
                required 
              />
            </FormGroup>

            <FormGroup label="Shop Address">
              <input 
                type="text" 
                placeholder="Full Shop Address"
                value={formData.shopAddress} 
                onChange={e => setFormData({...formData, shopAddress: e.target.value})} 
                className="input-base" 
                required 
              />
            </FormGroup>
          </div>
        </div>

        <div className="pt-8 border-t border-slate-50 flex flex-col md:flex-row justify-end gap-4">
          <button 
            type="button" 
            onClick={(e) => handleFormSubmit(e as any, true)}
            className="w-full md:w-auto px-10 py-5 bg-slate-100 text-slate-700 rounded-3xl font-black text-lg hover:bg-slate-200 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            SAVE & ADD ANOTHER
          </button>
          <button 
            type="submit" 
            className="w-full md:w-auto px-12 py-5 bg-slate-900 text-white rounded-3xl font-black text-xl hover:bg-slate-800 transition-all shadow-2xl active:scale-95 flex items-center justify-center gap-3"
          >
            SAVE TRANSACTION
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
          </button>
        </div>
      </form>

      <style>{`
        .input-base { 
          width: 100%; 
          padding: 16px 20px; 
          border-radius: 20px; 
          border: 2px solid #f1f5f9; 
          background-color: #f8fafc; 
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); 
          outline: none; 
          font-weight: 500;
          color: #1e293b;
        }
        .input-base:focus { 
          border-color: #3b82f6; 
          background-color: white;
          box-shadow: 0 10px 15px -3px rgba(59, 130, 246, 0.08);
          transform: translateY(-1px);
        }
        .input-base::placeholder {
          color: #cbd5e1;
        }
      `}</style>
    </div>
  );
};

const SectionHeader: React.FC<{ title: string; icon: React.ReactNode }> = ({ title, icon }) => (
  <div className="flex items-center gap-3 mb-6">
    <div className="p-2.5 bg-slate-100 rounded-xl text-slate-600">
      {icon}
    </div>
    <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">{title}</h3>
  </div>
);

const FormGroup: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
  <div className="flex flex-col gap-2">
    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">{label}</label>
    {children}
  </div>
);

const BillIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>;
const ShopIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>;

export default BillForm;

import React, { useState, useEffect, useRef } from 'react';
import { Bill, Recovery, RecoveryType } from '../types';

interface RecoveryFormProps {
  bills: Bill[];
  onSubmit: (recovery: Omit<Recovery, 'id'>) => void;
  currency: string;
}

const RecoveryForm: React.FC<RecoveryFormProps> = ({ bills, onSubmit, currency }) => {
  const [billSearch, setBillSearch] = useState('');
  const [selectedBill, setSelectedBill] = useState<Bill | null>(null);
  const [recoveryDate, setRecoveryDate] = useState(new Date().toISOString().split('T')[0]);
  const [type, setType] = useState<RecoveryType>(RecoveryType.OB);
  const [recoveryAmount, setRecoveryAmount] = useState('');
  const amountInputRef = useRef<HTMLInputElement>(null);

  const activeBills = bills.filter(b => b.balance > 0);

  const handleBillSelect = (bill: Bill) => {
    setSelectedBill(bill);
    setBillSearch(bill.billNumber);
    setRecoveryAmount('');
    // Auto focus amount input after a short delay
    setTimeout(() => amountInputRef.current?.focus(), 100);
  };

  const handleQuickAmount = (amount: number) => {
    if (!selectedBill) return;
    // Cap at bill balance
    const finalAmount = Math.min(amount, selectedBill.balance);
    setRecoveryAmount(finalAmount.toString());
  };

  const handleFullPayment = () => {
    if (!selectedBill) return;
    setRecoveryAmount(selectedBill.balance.toString());
  };

  const remainingBalance = selectedBill 
    ? selectedBill.balance - (Number(recoveryAmount) || 0) 
    : 0;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedBill || !recoveryAmount) return;

    const amount = Number(recoveryAmount);
    if (amount <= 0) {
      alert("Please enter a valid recovery amount.");
      return;
    }
    if (amount > selectedBill.balance) {
      alert("Recovery amount cannot exceed remaining balance!");
      return;
    }

    onSubmit({
      billNumber: selectedBill.billNumber,
      billDate: selectedBill.date,
      recoveryDate: recoveryDate,
      type: type,
      billAmountAtRecovery: selectedBill.balance,
      recoveryAmount: amount,
      remainingAmount: remainingBalance
    });

    // Reset after success
    setSelectedBill(null);
    setBillSearch('');
    setRecoveryAmount('');
  };

  const matchingBills = billSearch.length > 0 && !selectedBill
    ? activeBills.filter(b => 
        b.billNumber.toLowerCase().includes(billSearch.toLowerCase()) || 
        b.shopName.toLowerCase().includes(billSearch.toLowerCase())
      ).slice(0, 5)
    : [];

  return (
    <div className="max-w-6xl mx-auto animate-fadeIn">
      <div className="flex flex-col lg:flex-row gap-8 bg-slate-900 rounded-[40px] p-2 md:p-4 shadow-2xl overflow-hidden border border-slate-800">

        {/* Left Section: POS Controls */}
        <div className="flex-1 bg-white rounded-[32px] p-8 md:p-12 space-y-8">
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter">Recovery POS</h2>
            <p className="text-slate-400 font-medium">Fast payment processing and real-time ledger updates.</p>
          </div>

          <div className="space-y-6">
            {/* Bill Lookup */}
            <div className="relative">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block ml-1">Search Bill # or Shop</label>
              <div className="relative">
                <input 
                  type="text" 
                  autoFocus
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 font-bold text-slate-800 focus:border-blue-500 focus:outline-none transition-all"
                  placeholder="Type bill number..."
                  value={billSearch}
                  onChange={(e) => {
                    setBillSearch(e.target.value);
                    if (selectedBill) setSelectedBill(null);
                  }}
                />
                <svg className="absolute right-6 top-1/2 -translate-y-1/2 w-5 h-5 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>

              {/* Autocomplete Dropdown */}
              {matchingBills.length > 0 && (
                <div className="absolute z-50 mt-2 w-full bg-white rounded-2xl shadow-2xl border border-slate-100 overflow-hidden divide-y divide-slate-50">
                  {matchingBills.map(b => (
                    <button 
                      key={b.id} 
                      onClick={() => handleBillSelect(b)}
                      className="w-full px-6 py-4 text-left hover:bg-slate-50 flex justify-between items-center transition-colors"
                    >
                      <div>
                        <p className="font-black text-slate-900">{b.billNumber}</p>
                        <p className="text-xs text-slate-500 font-bold">{b.shopName}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-sm font-black text-blue-600">{currency} {b.balance.toLocaleString()}</p>
                        <p className="text-[10px] text-slate-300 font-bold uppercase">{b.date}</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Recovery Date */}
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block ml-1">Recovery Date</label>
                <input 
                  type="date" 
                  value={recoveryDate}
                  onChange={e => setRecoveryDate(e.target.value)}
                  className="w-full bg-slate-50 border-2 border-slate-100 rounded-2xl px-6 py-4 font-bold text-slate-800 focus:border-blue-500 focus:outline-none transition-all"
                />
              </div>

              {/* Type Toggle */}
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 block ml-1">Recovery Type</label>
                <div className="flex bg-slate-100 p-1.5 rounded-2xl">
                  <button 
                    type="button"
                    onClick={() => setType(RecoveryType.OB)}
                    className={`flex-1 py-3 rounded-xl text-sm font-black transition-all ${type === RecoveryType.OB ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                  >
                    OB (Order Booker)
                  </button>
                  <button 
                    type="button"
                    onClick={() => setType(RecoveryType.SM)}
                    className={`flex-1 py-3 rounded-xl text-sm font-black transition-all ${type === RecoveryType.SM ? 'bg-white shadow-md text-blue-600' : 'text-slate-500 hover:text-slate-800'}`}
                  >
                    SM (Sales Manager)
                  </button>
                </div>
              </div>
            </div>

            {/* Amount Input & Quick Selects */}
            <div className={`transition-all ${selectedBill ? 'opacity-100' : 'opacity-20 pointer-events-none'}`}>
              <div className="flex justify-between items-end mb-2 ml-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Recovery Amount ({currency})</label>
                {selectedBill && recoveryAmount && (
                  <span className={`text-[10px] font-black uppercase tracking-widest ${remainingBalance < 0 ? 'text-rose-500' : 'text-slate-400'}`}>
                    Suggested Remaining: {currency} {remainingBalance.toLocaleString()}
                  </span>
                )}
              </div>
              <div className="relative">
                <span className="absolute left-6 top-1/2 -translate-y-1/2 text-2xl font-black text-emerald-400 opacity-50">{currency}</span>
                <input 
                  ref={amountInputRef}
                  type="number" 
                  placeholder="0"
                  className={`w-full bg-slate-50 border-2 border-slate-100 rounded-2xl py-6 text-4xl font-black text-emerald-600 placeholder:text-slate-200 focus:border-emerald-500 focus:outline-none transition-all ${currency.length > 1 ? 'px-20' : 'px-16'}`}
                  value={recoveryAmount}
                  onChange={e => setRecoveryAmount(e.target.value)}
                />
              </div>

              {/* Quick Amount Buttons */}
