                <div className="space-y-6 pt-6 border-t border-slate-800">
                  <ReceiptLine label="Bill Date" value={selectedBill.date} />
                  <ReceiptLine label="Recovery Date" value={recoveryDate} />
                  <ReceiptLine label="Type" value={type} />
