                </div>
                <div className="bg-slate-900 p-8 rounded-[40px] shadow-xl text-white print:bg-slate-100 print:text-black">
                    <p className="text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Net Balance</p>
