type ImportType = 'bills' | 'customers' | 'obs';

const ImportPage: React.FC<Props> = ({ onImportBills, onImportCustomers, onImportOBs, customers, obs, currency }) => {
  const [stage, setStage] = useState<'type_selection' | 'upload' | 'mapping' | 'preview'>('type_selection');
  const [importType, setImportType] = useState<ImportType>('bills');
  const [rawText, setRawText] = useState('');
  const [parsedData, setParsedData] = useState<string[][]>([]);
  const [mapping, setMapping] = useState<Record<string, number>>({});

  // Final parsed results
  const [billResults, setBillResults] = useState<Omit<Bill, 'id' | 'recovery' | 'balance'>[]>([]);
  const [customerResults, setCustomerResults] = useState<Omit<Customer, 'id'>[]>([]);
  const [obResults, setObResults] = useState<Omit<OrderBooker, 'id'>[]>([]);

  const billFields = [
    { key: 'date', label: 'Bill Date (YYYY-MM-DD)', required: true },
    { key: 'customerCode', label: 'Customer Code', required: true },
    { key: 'obCode', label: 'OB Code', required: true },
    { key: 'billNumber', label: 'Bill Number', required: true },
    { key: 'shopName', label: 'Shop Name (Auto if Code matches)', required: false },
    { key: 'shopAddress', label: 'Shop Address', required: false },
    { key: 'billAmount', label: 'Bill Amount', required: true }
  ];

  const customerFields = [
    { key: 'code', label: 'Customer Code', required: true },
    { key: 'name', label: 'Shop Name', required: true },
    { key: 'obCode', label: 'OB Code', required: true },
    { key: 'address', label: 'Address', required: true }
  ];

  const obFields = [
    { key: 'code', label: 'OB Code', required: true },
    { key: 'name', label: 'Name', required: true },
    { key: 'phone', label: 'Phone Number', required: true }
  ];

  const currentFields = importType === 'bills' ? billFields : importType === 'customers' ? customerFields : obFields;

  const handleStartImportProcess = (type: ImportType) => {
    setImportType(type);
    setStage('upload');
  };

  const handleTextProcess = () => {
    if (!rawText.trim()) return;
    const lines = rawText.split('\n').map(line => line.split(/[,\t]/).map(cell => cell.trim()));
    setParsedData(lines);
    setStage('mapping');
  };

  const handleStartPreview = () => {
    if (importType === 'bills') {
      const results: Omit<Bill, 'id' | 'recovery' | 'balance'>[] = parsedData.slice(1).map(row => {
        const customerCode = row[mapping.customerCode] || '';
        const matchedCustomer = customers.find(c => c.code.toLowerCase() === customerCode.toLowerCase());

        return {
          date: row[mapping.date] || new Date().toISOString().split('T')[0],
          customerCode,
          obCode: matchedCustomer ? matchedCustomer.obCode : (row[mapping.obCode] || ''),
          billNumber: row[mapping.billNumber] || `IMP-${Math.floor(1000 + Math.random() * 9000)}`,
          shopName: matchedCustomer ? matchedCustomer.name : (row[mapping.shopName] || 'Imported Shop'),
          shopAddress: matchedCustomer ? matchedCustomer.address : (row[mapping.shopAddress] || ''),
          billType: BillType.FOOD,
          billAmount: parseFloat(row[mapping.billAmount]) || 0
        };
      }).filter(b => b.billAmount > 0);
      setBillResults(results);
    } else if (importType === 'customers') {
      const results: Omit<Customer, 'id'>[] = parsedData.slice(1).map(row => ({
        code: (row[mapping.code] || '').toUpperCase(),
        name: row[mapping.name] || 'Unnamed Shop',
        obCode: (row[mapping.obCode] || '').toUpperCase(),
        address: row[mapping.address] || 'No Address'
      })).filter(c => c.code);
      setCustomerResults(results);
    } else {
      const results: Omit<OrderBooker, 'id'>[] = parsedData.slice(1).map(row => ({
        code: (row[mapping.code] || '').toUpperCase(),
        name: row[mapping.name] || 'Unnamed OB',
        phone: row[mapping.phone] || 'No Phone'
      })).filter(ob => ob.code);
      setObResults(results);
    }
    setStage('preview');
  };

  const finalize = () => {
    if (importType === 'bills') onImportBills(billResults);
    else if (importType === 'customers') onImportCustomers(customerResults);
    else onImportOBs(obResults);
  };

  return (
    <div className="max-w-5xl mx-auto animate-fadeIn pb-20">
      {stage === 'type_selection' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-12">
            <ImportModeCard 
                title="Bills" 
                desc="Import daily credit bill batches from spreadsheets." 
                icon={<MoneyIcon/>}
                onClick={() => handleStartImportProcess('bills')}
                color="blue"
            />
            <ImportModeCard 
                title="Customers" 
                desc="Upload your entire shop database or new customer lists." 
                icon={<UsersIcon/>}
                onClick={() => handleStartImportProcess('customers')}
                color="emerald"
            />
            <ImportModeCard 
                title="Order Bookers" 
                desc="Bulk register your team of Order Bookers." 
                icon={<BriefcaseIcon/>}
                onClick={() => handleStartImportProcess('obs')}
                color="slate"
            />
        </div>
      )}

      {stage === 'upload' && (
        <div className="bg-white p-12 rounded-[40px] shadow-sm border border-slate-100 text-center space-y-8 animate-slideUp">
          <div className="flex justify-center">
            <div className="w-20 h-20 bg-slate-50 text-slate-400 rounded-full flex items-center justify-center">
              <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            </div>
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tighter capitalize">Import {importType === 'obs' ? 'Order Bookers' : importType}</h2>
            <p className="text-slate-500 mt-2 max-w-md mx-auto">Copy data from Excel and paste it below. Include headers for easier mapping.</p>
          </div>

          <textarea 
            className="w-full h-64 p-8 bg-slate-50 rounded-[32px] border-2 border-slate-200 focus:border-blue-500 focus:outline-none transition-all font-mono text-xs leading-relaxed"
            placeholder={`Example:
Code,Name,Phone
OB-01,John Doe,123-456-7890`}
            value={rawText}
            onChange={e => setRawText(e.target.value)}
          />

          <div className="flex gap-4 justify-center">
            <button 
                onClick={handleTextProcess}
                disabled={!rawText.trim()}
                className="px-12 py-4 bg-slate-900 text-white rounded-2xl font-black text-lg hover:bg-slate-800 transition-all disabled:opacity-50 active:scale-95 shadow-xl"
            >
                Process Data
            </button>
            <button onClick={() => setStage('type_selection')} className="px-8 py-4 bg-slate-100 text-slate-600 rounded-2xl font-bold hover:bg-slate-200">Cancel</button>
          </div>
        </div>
      )}

      {stage === 'mapping' && (
        <div className="bg-white p-8 md:p-12 rounded-[40px] shadow-sm border border-slate-100 animate-slideUp">
            <h2 className="text-3xl font-black text-slate-900 mb-2 tracking-tighter">Field Mapping</h2>
            <p className="text-slate-500 mb-10">Match our required fields to your spreadsheet columns.</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                {currentFields.map(field => (
                    <div key={field.key} className="flex flex-col gap-2 p-5 bg-slate-50 rounded-[24px] border border-slate-100">
                        <div className="flex justify-between items-center px-1">
                            <span className="font-bold text-slate-800 text-sm">{field.label}</span>
                            {field.required && <span className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Required</span>}
                        </div>
                        <select 
                            className="bg-white border border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-100 appearance-none shadow-sm"
                            onChange={e => setMapping(prev => ({...prev, [field.key]: parseInt(e.target.value)}))}
                            defaultValue=""
                        >
                            <option value="">-- Choose Column --</option>
                            {parsedData[0].map((header, idx) => (
                                <option key={idx} value={idx}>{header || `Column ${idx+1}`}</option>
                            ))}
                        </select>
                    </div>
                ))}
            </div>

            <div className="mt-12 flex gap-4">
                <button onClick={handleStartPreview} className="flex-grow bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-lg shadow-blue-100 active:scale-95 transition-all">Review & Preview</button>
                <button onClick={() => setStage('upload')} className="px-8 bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold">Back to Paste</button>
            </div>
        </div>
      )}

      {stage === 'preview' && (
        <div className="bg-white p-8 md:p-12 rounded-[40px] shadow-sm border border-slate-100 animate-slideUp">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10">
                <div>
                    <h2 className="text-3xl font-black text-slate-900 tracking-tighter">Final Review</h2>
                    <p className="text-slate-500">Previewing <span className="font-black text-slate-900">{importType === 'bills' ? billResults.length : importType === 'customers' ? customerResults.length : obResults.length}</span> entries.</p>
                </div>
                <div className="flex gap-3">
                    <button onClick={finalize} className="bg-emerald-600 text-white px-10 py-4 rounded-2xl font-black text-lg shadow-xl shadow-emerald-100 active:scale-95 transition-all">Confirm Import</button>
                    <button onClick={() => setStage('mapping')} className="bg-slate-100 text-slate-600 px-6 py-4 rounded-2xl font-bold">Adjust Mapping</button>
                </div>
            </div>

            <div className="overflow-x-auto border border-slate-100 rounded-[32px] shadow-inner bg-slate-50/30">
                <table className="w-full text-left">
                    <thead className="bg-slate-100/50 text-[10px] uppercase font-black text-slate-400 tracking-widest">
                        {importType === 'bills' ? (
                          <tr>
                              <th className="px-6 py-5">Date</th>
                              <th className="px-6 py-5">Bill #</th>
                              <th className="px-6 py-5">Customer Info</th>
                              <th className="px-6 py-5 text-right">Amount</th>
                          </tr>
                        ) : importType === 'customers' ? (
                          <tr>
                              <th className="px-6 py-5">Code</th>
                              <th className="px-6 py-5">Shop Name</th>
                              <th className="px-6 py-5">OB Code</th>
                              <th className="px-6 py-5">Full Address</th>
                          </tr>
                        ) : (
                          <tr>
                              <th className="px-6 py-5">Code</th>
                              <th className="px-6 py-5">Name</th>
                              <th className="px-6 py-5">Phone</th>
                          </tr>
                        )}
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                        {importType === 'bills' ? (
                          billResults.map((b, i) => (
                            <tr key={i} className="text-sm hover:bg-white transition-colors">
                                <td className="px-6 py-5 font-medium text-slate-600">{b.date}</td>
                                <td className="px-6 py-5 font-black text-slate-900">{b.billNumber}</td>
                                <td className="px-6 py-5">
                                    <p className="font-bold text-slate-800">{b.shopName}</p>
                                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tighter">{b.customerCode}</p>
                                </td>
                                <td className="px-6 py-5 text-right font-black text-blue-600">{currency} {b.billAmount.toLocaleString()}</td>
                            </tr>
                          ))
                        ) : importType === 'customers' ? (
                          customerResults.map((c, i) => (
                            <tr key={i} className="text-sm hover:bg-white transition-colors">
                                <td className="px-6 py-5 font-black text-slate-900">{c.code}</td>
                                <td className="px-6 py-5 font-bold text-slate-700">{c.name}</td>
                                <td className="px-6 py-5"><span className="bg-slate-200 px-2 py-0.5 rounded text-[10px] font-bold">{c.obCode}</span></td>
                                <td className="px-6 py-5 text-slate-500">{c.address}</td>
                            </tr>
                          ))
                        ) : (
                          obResults.map((ob, i) => (
                            <tr key={i} className="text-sm hover:bg-white transition-colors">
                                <td className="px-6 py-5 font-black text-slate-900">{ob.code}</td>
                                <td className="px-6 py-5 font-bold text-slate-700">{ob.name}</td>
                                <td className="px-6 py-5 text-slate-500">{ob.phone}</td>
                            </tr>
                          ))
                        )}
                    </tbody>
                </table>
            </div>
        </div>
      )}
    </div>
  );
};

const ImportModeCard = ({ title, desc, icon, onClick, color }: any) => {
    const themes = {
        blue: "bg-blue-600 shadow-blue-100",
        emerald: "bg-emerald-600 shadow-emerald-100",
        slate: "bg-slate-700 shadow-slate-100"
    };
    return (
        <button 
            onClick={onClick}
            className="group relative bg-white p-10 rounded-[48px] border-2 border-slate-100 shadow-sm hover:shadow-2xl hover:border-slate-200 transition-all text-left flex flex-col items-start overflow-hidden"
        >
            <div className={`w-16 h-16 rounded-[20px] flex items-center justify-center mb-6 transition-transform group-hover:scale-110 shadow-lg ${themes[color as keyof typeof themes]} text-white`}>
                {icon}
            </div>
            <h3 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">Import {title}</h3>
            <p className="text-slate-500 font-medium leading-relaxed">{desc}</p>
            <div className="mt-8 flex items-center gap-2 font-black text-xs uppercase tracking-widest text-slate-400 group-hover:text-slate-900 transition-colors">
                Start Import <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M17 8l4 4m0 0l-4 4m4-4H3" /></svg>
            </div>
        </button>
    );
};

const MoneyIcon = () => <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>;
const UsersIcon = () => <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z" /></svg>;
const BriefcaseIcon = () => <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" /></svg>;

export default ImportPage;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) setCurrentUser(JSON.parse(savedUserJson));

        setIsDbReady(true);
        refreshData();
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleCurrencyChange = (newSymbol: string) => {
    setCurrencySymbol(newSymbol);
    setSetting('app_currency', newSymbol);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const quickAddCustomer = (customer: Omit<Customer, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO customers (id, code, name, address, obCode)
      VALUES (?, ?, ?, ?, ?)
    `, [id, customer.code, customer.name, customer.address, customer.obCode]);
    refreshData();
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry Booting</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Wipe & Reset Database</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
            </div>
          </div>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />
              <NavItem id="themes" label="Appearance" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
              <NavItem id="summary" label="Credit Summary" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2m3 2v-4m3 4v-6m2 10H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="ob-ledger" label="OB Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>} />
              <NavItem id="customer-ledger" label="Customer Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 14v3m4-3v3m4-3v3M3 21h18M3 10h18M3 7l9-4 9 4M4 10h16v11H4V10z" /></svg>} />
            </>
          )}
        </nav>

        <div className="mt-auto pt-6 border-t border-slate-100/10 space-y-4">
           <div className={`rounded-2xl p-4 flex items-center gap-3 ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/5 text-white' : 'bg-slate-900 text-white'}`}>
              <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${getThemeColor()}`}>
                {currentUser.name.charAt(0)}
              </div>
              <div>
                <p className="text-xs font-bold truncate max-w-[120px]">{currentUser.name}</p>
                <p className="text-[10px] text-slate-500 uppercase font-black">{currentUser.role}</p>
              </div>
           </div>
           <button onClick={handleLogout} className="w-full flex items-center justify-center gap-2 px-6 py-3 rounded-xl font-bold text-rose-500 hover:bg-rose-500/10 transition-all text-xs uppercase">
             <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
             Logout Session
           </button>
        </div>
      </aside>

      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (isAdmin ? <Dashboard bills={bills} recoveries={recoveries} currency={currencySymbol} /> : <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} currency={currencySymbol} />)}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} currency={currencySymbol} onAddCustomer={quickAddCustomer} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} currency={currencySymbol} />}
        {isAdmin && (
          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} currency={currencySymbol} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} setCustomers={() => {}} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} setObs={() => {}} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} currency={currencySymbol} />}
            {activeTab === 'import' && <ImportPage onImportBills={handleBulkImportBills} onImportCustomers={handleBulkImportCustomers} onImportOBs={handleBulkImportOBs} customers={customers} obs={obs} currency={currencySymbol} />}
            {activeTab === 'themes' && <ThemePage currentTheme={theme} currentCurrency={currencySymbol} onThemeChange={handleThemeChange} onCurrencyChange={handleCurrencyChange} />}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} currency={currencySymbol} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage item={editingItem} customers={customers} obs={obs} bills={bills} currency={currencySymbol} onUpdateBill={updateBill} onUpdateRecovery={() => {}} onUpdateCustomer={updateCustomer} onUpdateOB={updateOB} onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { BillType, Bill, Customer, OrderBooker } from '../types';

interface BillFormProps {
  customers: Customer[];
  obs: OrderBooker[];
  onSubmit: (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage?: boolean) => void;
  currency: string;
  onAddCustomer: (customer: Omit<Customer, 'id'>) => void;
}

const BillForm: React.FC<BillFormProps> = ({ customers, obs, onSubmit, currency, onAddCustomer }) => {
  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    customerCode: '',
    obCode: '',
    billNumber: '',
    shopName: '',
    shopAddress: '',
    billType: BillType.FOOD,
    billAmount: ''
  });

  const [isAddingCustomer, setIsAddingCustomer] = useState(false);
  const [newCust, setNewCust] = useState({ code: '', name: '', address: '', obCode: '' });

  // Auto-fill logic for shop details based on customer code
  useEffect(() => {
    const customer = customers.find(c => c.code.toLowerCase() === formData.customerCode.toLowerCase());
    if (customer) {
      setFormData(prev => ({
        ...prev,
        shopName: customer.name,
        shopAddress: customer.address,
        obCode: customer.obCode || prev.obCode // Use default OB from customer if available
      }));
    }
  }, [formData.customerCode, customers]);

  const handleReset = () => {
    if (window.confirm("Clear all fields and start a new bill?")) {
      setFormData({
        date: new Date().toISOString().split('T')[0],
        customerCode: '',
        obCode: '',
        billNumber: '',
        shopName: '',
        shopAddress: '',
        billType: BillType.FOOD,
        billAmount: ''
      });
    }
  };

  const handleFormSubmit = (e: React.FormEvent, stayOnPage: boolean = false) => {
    e.preventDefault();
    if (!formData.billAmount || isNaN(Number(formData.billAmount))) return;
    if (!formData.billNumber.trim()) {
      alert("Please enter a Bill Number");
      return;
    }

    onSubmit({ ...formData, billAmount: Number(formData.billAmount) }, stayOnPage);

    // Reset form for next entry
    setFormData({
      date: new Date().toISOString().split('T')[0],
      customerCode: '',
      obCode: '',
      billNumber: '',
      shopName: '',
      shopAddress: '',
      billType: BillType.FOOD,
      billAmount: ''
    });
  };

  const handleQuickAddCustomer = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCust.code || !newCust.name || !newCust.obCode) {
      alert("Please fill all required fields for the new customer.");
      return;
    }
    if (customers.some(c => c.code.toUpperCase() === newCust.code.toUpperCase())) {
      alert("A customer with this code already exists.");
      return;
    }

    onAddCustomer(newCust);
    setFormData(prev => ({ ...prev, customerCode: newCust.code.toUpperCase() }));
    setNewCust({ code: '', name: '', address: '', obCode: '' });
    setIsAddingCustomer(false);
  };

  return (
    <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-100 max-w-5xl mx-auto animate-slideUp">
      <div className="flex justify-between items-start mb-10 border-b border-slate-50 pb-8">
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter">New Billing Entry</h2>
          <p className="text-slate-500 mt-2 font-medium">Organize your records by filling in transaction and customer details.</p>
        </div>
        <button 
          type="button" 
          onClick={handleReset}
          className="flex items-center gap-2 px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-2xl text-xs font-black uppercase transition-all shadow-sm active:scale-95"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          Quick New
        </button>
      </div>

      <form onSubmit={(e) => handleFormSubmit(e, false)} className="space-y-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12">

          {/* Column 1: Transaction Details */}
          <div className="space-y-6">
            <SectionHeader title="Transaction Details" icon={<BillIcon />} />

            <FormGroup label="Bill Date">
              <input type="date" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} className="input-base" required />
            </FormGroup>

            <FormGroup label="Bill Number">
              <input 
                type="text" 
                placeholder="Enter Bill #"
                value={formData.billNumber} 
                onChange={e => setFormData({...formData, billNumber: e.target.value})} 
                className="input-base font-bold text-slate-900" 
                required
              />
            </FormGroup>

            <FormGroup label="Bill Type">
              <select value={formData.billType} onChange={e => setFormData({...formData, billType: e.target.value as BillType})} className="input-base font-bold text-slate-900">
                {Object.values(BillType).map(type => <option key={type} value={type}>{type}</option>)}
              </select>
            </FormGroup>

            <FormGroup label={`Bill Amount (${currency})`}>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">{currency}</span>
                <input 
                  type="number" 
                  placeholder="0" 
                  value={formData.billAmount} 
                  onChange={e => setFormData({...formData, billAmount: e.target.value})} 
                  className={`input-base font-black text-2xl text-blue-600 ${currency.length > 1 ? 'pl-14' : 'pl-10'}`} 
                  required 
                />
              </div>
            </FormGroup>
          </div>

          {/* Column 2: Customer & Shop Info */}
          <div className="space-y-6">
            <SectionHeader title="Customer Information" icon={<ShopIcon />} />

            <div className="space-y-2">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Customer Code</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <input 
                    type="text" 
                    placeholder="e.g. C001"
                    value={formData.customerCode} 
                    onChange={e => setFormData({...formData, customerCode: e.target.value})}
                    className={`input-base uppercase ${customers.some(c => c.code.toLowerCase() === formData.customerCode.toLowerCase()) ? 'border-emerald-500 ring-emerald-100 ring-4' : ''}`}
                    required
                  />
                  {customers.some(c => c.code.toLowerCase() === formData.customerCode.toLowerCase()) && (
                    <span className="absolute right-4 top-1/2 -translate-y-1/2 bg-emerald-100 text-emerald-600 text-[10px] px-2 py-1 rounded-lg font-black tracking-widest uppercase">Matched</span>
                  )}
                </div>
                <button 
                  type="button"
                  onClick={() => setIsAddingCustomer(true)}
                  className="bg-blue-600 text-white px-4 rounded-2xl font-bold text-xs hover:bg-blue-700 transition-all shadow-lg active:scale-95 flex items-center justify-center"
                  title="Add New Customer"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
                </button>
              </div>
            </div>

            <FormGroup label="Order Booker (OB)">
              <select 
                value={formData.obCode} 
                onChange={e => setFormData({...formData, obCode: e.target.value})}
                className="input-base"
                required
              >
                <option value="">Select OB</option>
                {obs.map(ob => (
                  <option key={ob.id} value={ob.code}>{ob.name} ({ob.code})</option>
                ))}
              </select>
            </FormGroup>

            <FormGroup label="Shop Name">
              <input 
                type="text" 
                placeholder="Shop Name"
                value={formData.shopName} 
                onChange={e => setFormData({...formData, shopName: e.target.value})} 
                className="input-base" 
                required 
              />
            </FormGroup>

            <FormGroup label="Shop Address">
              <input 
                type="text" 
                placeholder="Full Shop Address"
                value={formData.shopAddress} 
                onChange={e => setFormData({...formData, shopAddress: e.target.value})} 
                className="input-base" 
                required 
              />
            </FormGroup>
          </div>
        </div>

        <div className="pt-8 border-t border-slate-50 flex flex-col md:flex-row justify-end gap-4">
          <button 
            type="button" 
            onClick={(e) => handleFormSubmit(e as any, true)}
            className="w-full md:w-auto px-10 py-5 bg-slate-100 text-slate-700 rounded-3xl font-black text-lg hover:bg-slate-200 transition-all active:scale-95 flex items-center justify-center gap-2"
          >
            SAVE & ADD ANOTHER
          </button>
          <button 
            type="submit" 
            className="w-full md:w-auto px-12 py-5 bg-slate-900 text-white rounded-3xl font-black text-xl hover:bg-slate-800 transition-all shadow-2xl active:scale-95 flex items-center justify-center gap-3"
          >
            SAVE TRANSACTION
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>
          </button>
        </div>
      </form>

      {/* Quick Add Customer Modal */}
      {isAddingCustomer && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-sm p-6 animate-fadeIn">
          <div className="bg-white w-full max-w-lg rounded-[40px] shadow-2xl p-10 relative animate-slideUp">
            <button 
              onClick={() => setIsAddingCustomer(false)}
              className="absolute top-8 right-8 text-slate-400 hover:text-slate-600 transition-colors"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>

            <div className="mb-8">
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">Register New Shop</h3>
              <p className="text-slate-500 text-sm font-medium">Add a new customer to the database instantly.</p>
            </div>

            <form onSubmit={handleQuickAddCustomer} className="space-y-5">
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 block ml-1">Shop Code (Unique)</label>
                <input 
                  type="text" 
                  autoFocus
                  className="input-base uppercase" 
                  placeholder="e.g. C100" 
                  value={newCust.code} 
                  onChange={e => setNewCust({...newCust, code: e.target.value})} 
                  required 
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 block ml-1">Shop / Client Name</label>
                <input 
                  type="text" 
                  className="input-base" 
                  placeholder="Official Shop Name" 
                  value={newCust.name} 
                  onChange={e => setNewCust({...newCust, name: e.target.value})} 
                  required 
                />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 block ml-1">Assign Order Booker</label>
                <select 
                  className="input-base" 
                  value={newCust.obCode} 
                  onChange={e => setNewCust({...newCust, obCode: e.target.value})} 
                  required
                >
                  <option value="">Select OB</option>
                  {obs.map(ob => (
                    <option key={ob.id} value={ob.code}>{ob.name} ({ob.code})</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 block ml-1">Full Address</label>
                <input 
                  type="text" 
                  className="input-base" 
                  placeholder="Locality, City" 
                  value={newCust.address} 
                  onChange={e => setNewCust({...newCust, address: e.target.value})} 
                  required 
                />
              </div>

              <div className="pt-4">
                <button type="submit" className="w-full bg-blue-600 text-white py-4 rounded-2xl font-black text-lg shadow-xl shadow-blue-500/20 hover:bg-blue-700 transition-all active:scale-95">
                  REGISTER CUSTOMER
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <style>{`
        .input-base { 
          width: 100%; 
          padding: 16px 20px; 
          border-radius: 20px; 
          border: 2px solid #f1f5f9; 
          background-color: #f8fafc; 
          transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); 
          outline: none; 
          font-weight: 500;
          color: #1e293b;
        }
        .input-base:focus { 
          border-color: #3b82f6; 
          background-color: white;
          box-shadow: 0 10px 15px -3px rgba(59, 130, 246, 0.08);
          transform: translateY(-1px);
        }
        .input-base::placeholder {
          color: #cbd5e1;
        }
        .animate-fadeIn { animation: fadeIn 0.3s ease-out; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
      `}</style>
    </div>
  );
};

const SectionHeader: React.FC<{ title: string; icon: React.ReactNode }> = ({ title, icon }) => (
  <div className="flex items-center gap-3 mb-6">
    <div className="p-2.5 bg-slate-100 rounded-xl text-slate-600">
      {icon}
    </div>
    <h3 className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">{title}</h3>
  </div>
);

const FormGroup: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => (
  <div className="flex flex-col gap-2">
    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">{label}</label>
    {children}
  </div>
);

const BillIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>;
const ShopIcon = () => <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>;

export default BillForm;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) setCurrentUser(JSON.parse(savedUserJson));

        setIsDbReady(true);
        refreshData();
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleCurrencyChange = (newSymbol: string) => {
    setCurrencySymbol(newSymbol);
    setSetting('app_currency', newSymbol);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const addCustomer = (customer: Omit<Customer, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO customers (id, code, name, address, obCode)
      VALUES (?, ?, ?, ?, ?)
    `, [id, customer.code, customer.name, customer.address, customer.obCode]);
    refreshData();
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm("Delete customer? This will not remove their historical bills.")) {
      runCommand("DELETE FROM customers WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addOB = (ob: Omit<OrderBooker, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO obs (id, code, name, phone)
      VALUES (?, ?, ?, ?)
    `, [id, ob.code, ob.name, ob.phone]);
    refreshData();
  };

  const deleteOB = (id: string) => {
    if (window.confirm("Delete Order Booker?")) {
      runCommand("DELETE FROM obs WHERE id = ?", [id]);
      refreshData();
    }
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry Booting</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Wipe & Reset Database</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
            </div>
          </div>
        </div>

        <nav className="flex flex-col gap-2">
          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Workspace</p>
          <NavItem id="dashboard" label="Dashboard" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" /></svg>} />

          <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Operations</p>
          <NavItem id="bills" label="New Billing" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v3m0 0v3m0-3h3m-3 0H9m12 0a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
          <NavItem id="recovery" label="Recovery POS" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 9V7a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2m2 4h10a2 2 0 002-2v-6a2 2 0 00-2-2H9a2 2 0 00-2 2v6a2 2 0 002 2zm7-5a2 2 0 11-4 0 2 2 0 014 0z" /></svg>} />

          {isAdmin && (
            <>
              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Admin Center</p>
              <NavItem id="ledger" label="Transaction Ledger" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" /></svg>} />
              <NavItem id="customers" label="Shops / Customers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" /></svg>} />
              <NavItem id="obs" label="Order Bookers" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>} />
              <NavItem id="import" label="Bulk Import" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>} />
              <NavItem id="themes" label="Appearance" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" /></svg>} />

              <p className="px-6 text-[10px] font-black text-slate-500 uppercase tracking-widest mt-6 mb-2">Reports</p>
              <NavItem id="today" label="Today's Activity" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
