              <h3 className="text-2xl font-black tracking-tight flex items-center gap-3">
                <svg className="w-8 h-8 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M9 19l3 3m0 0l3-3m-3 3V10" /></svg>
                Instant Data Push
              </h3>
              <p className="text-slate-400 text-sm leading-relaxed">Pushes all local SQLite tables to your online storage. This creates a secure remote backup of your current database state.</p>
           </div>

           <div className="mt-10 space-y-4">
              <div className="flex justify-between items-center text-xs font-bold text-slate-500 uppercase tracking-widest px-1">
                 <span>Last Sync</span>
                 <span className="text-slate-300">{syncState.lastSync || 'Never'}</span>
              </div>
              <button 
                onClick={onSyncNow}
                disabled={!syncUrl || syncState.status === 'syncing'}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white py-5 rounded-2xl font-black text-xl transition-all flex items-center justify-center gap-3"
              >
                {syncState.status === 'syncing' ? (
                  <div className="w-6 h-6 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                ) : 'SYNC TO CLOUD'}
              </button>
           </div>
        </div>
      </div>

      {/* Developer Help Section */}
      <div className="bg-blue-50 border border-blue-100 p-10 rounded-[48px] space-y-6">
         <h4 className="text-xl font-black text-blue-900 flex items-center gap-3">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            How to setup Online Storage
         </h4>

         <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-3">
                <p className="text-blue-800 font-bold flex items-center gap-2">
                   <span className="w-6 h-6 bg-blue-200 text-blue-800 rounded-full flex items-center justify-center text-xs">1</span>
                   Option A: Google Sheets
                </p>
                <p className="text-blue-700 text-sm leading-relaxed">Open a Sheet &gt; Extensions &gt; Apps Script. Paste a script that handles <b>doPost(e)</b>. Publish it as a Web App (Anyone) and copy the URL into the settings above.</p>
            </div>
            <div className="space-y-3">
                <p className="text-blue-800 font-bold flex items-center gap-2">
                   <span className="w-6 h-6 bg-blue-200 text-blue-800 rounded-full flex items-center justify-center text-xs">2</span>
                   Option B: Python Backend
                </p>
                <p className="text-blue-700 text-sm leading-relaxed">Create a simple Flask or FastAPI app with a POST route. This app can use <b>gspread</b> or <b>pandas</b> to write the incoming JSON data to an online file.</p>
            </div>
         </div>
      </div>
    </div>
  );
};

export default CloudSyncPage;

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType, SyncState } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting, getAllDataForSync } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';
import CloudSyncPage from './components/CloudSyncPage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes' | 'cloud';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  // Cloud Sync State
  const [syncUrl, setSyncUrl] = useState<string>('');
  const [syncState, setSyncState] = useState<SyncState>({ lastSync: null, status: 'idle' });

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUrl = getSetting('cloud_sync_url');
        if (savedUrl) setSyncUrl(savedUrl);

        const savedLastSync = getSetting('last_sync_time');
        if (savedLastSync) setSyncState(prev => ({ ...prev, lastSync: savedLastSync }));

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) setCurrentUser(JSON.parse(savedUserJson));

        setIsDbReady(true);
        refreshData();
      } catch (err: any) {
        console.error("Initialization error:", err);
        setDbError(err.message || "Failed to initialize the database engine.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("Failed to refresh data from SQLite", e);
    }
  };

  const handleSyncToCloud = async () => {
    if (!syncUrl) return;
    setSyncState(prev => ({ ...prev, status: 'syncing' }));

    try {
      const payload = getAllDataForSync();
      const response = await fetch(syncUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) throw new Error("Connection established but endpoint returned error.");

      const now = new Date().toLocaleString();
      setSyncState({ lastSync: now, status: 'success' });
      setSetting('last_sync_time', now);
    } catch (err: any) {
      setSyncState(prev => ({ ...prev, status: 'error', errorMessage: err.message }));
      alert("Cloud Sync Failed: " + err.message);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleCurrencyChange = (newSymbol: string) => {
    setCurrencySymbol(newSymbol);
    setSetting('app_currency', newSymbol);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const addCustomer = (customer: Omit<Customer, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO customers (id, code, name, address, obCode)
      VALUES (?, ?, ?, ?, ?)
    `, [id, customer.code, customer.name, customer.address, customer.obCode]);
    refreshData();
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm("Delete customer? This will not remove their historical bills.")) {
      runCommand("DELETE FROM customers WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addOB = (ob: Omit<OrderBooker, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO obs (id, code, name, phone)
      VALUES (?, ?, ?, ?)
    `, [id, ob.code, ob.name, ob.phone]);
    refreshData();
  };

  const deleteOB = (id: string) => {
    if (window.confirm("Delete Order Booker?")) {
      runCommand("DELETE FROM obs WHERE id = ?", [id]);
      refreshData();
    }
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Start Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry Booting</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Wipe & Reset Database</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
