/**
 * database.ts
 * Relational SQLite persistence layer for BillTrack Pro.
 * Uses sql.js (WASM) and IndexedDB for permanent browser-side storage.
 */

let db: any = null;
let SQL_LIB: any = null;
const DB_NAME = 'billtrack_pro_db_v1';
const STORE_NAME = 'sqlite_file';

/**
 * Loads the SQL.js library via a script tag.
 */
const loadSqlLibrary = (): Promise<any> => {
  return new Promise((resolve, reject) => {
    if ((window as any).initSqlJs) {
      resolve((window as any).initSqlJs);
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/sql.js@1.12.0/dist/sql-wasm.js';
    script.async = true;

    const timeout = setTimeout(() => {
      reject(new Error("Timeout loading SQLite engine (sql-wasm.js). Please check your internet connection."));
    }, 15000);

    script.onload = () => {
      clearTimeout(timeout);
      if ((window as any).initSqlJs) {
        resolve((window as any).initSqlJs);
      } else {
        reject(new Error("SQLite engine library loaded but global initSqlJs not found."));
      }
    };

    script.onerror = () => {
      clearTimeout(timeout);
      reject(new Error("Failed to load SQL.js library from CDN. Check your network or firewall."));
    };

    document.head.appendChild(script);
  });
};

/**
 * Initializes the SQLite database. 
 */
export const initDB = async () => {
  try {
    console.info("Database: Loading SQL Library...");
    const initSqlJs = await loadSqlLibrary();

    console.info("Database: Fetching WASM binary...");
    const wasmResponse = await fetch('https://cdn.jsdelivr.net/npm/sql.js@1.12.0/dist/sql-wasm.wasm');
    if (!wasmResponse.ok) throw new Error(`Could not fetch SQLite WASM binary. Status: ${wasmResponse.status}`);
    const wasmBinary = await wasmResponse.arrayBuffer();

    console.info("Database: Initializing SQL Engine...");
    SQL_LIB = await initSqlJs({ wasmBinary });
    const savedData = await loadFromIndexedDB();

    if (savedData && savedData.byteLength > 0) {
      console.info("Database: Loading existing data from storage...");
      try {
        db = new SQL_LIB.Database(new Uint8Array(savedData));
      } catch (err) {
        console.warn("Database: Local storage file corrupted, starting fresh.", err);
        db = new SQL_LIB.Database();
      }
    } else {
      console.info("Database: Creating new database instance...");
      db = new SQL_LIB.Database();
    }

    createSchema();
    console.info("Database: Initialized successfully.");
    return db;
  } catch (error) {
    console.error("Database: Initialization error:", error);
    throw error;
  }
};

const createSchema = () => {
  if (!db) return;
  try {
    db.run(`
      CREATE TABLE IF NOT EXISTS settings (
        key TEXT PRIMARY KEY,
        value TEXT
      );

      CREATE TABLE IF NOT EXISTS customers (
        id TEXT PRIMARY KEY,
        code TEXT UNIQUE,
        name TEXT,
        address TEXT,
        obCode TEXT
      );

      CREATE TABLE IF NOT EXISTS obs (
        id TEXT PRIMARY KEY,
        code TEXT UNIQUE,
        name TEXT,
        phone TEXT
      );

      CREATE TABLE IF NOT EXISTS bills (
        id TEXT PRIMARY KEY,
        date TEXT,
        customerCode TEXT,
        obCode TEXT,
        billNumber TEXT UNIQUE,
        shopName TEXT,
        shopAddress TEXT,
        billType TEXT,
        billAmount REAL,
        recovery REAL,
        balance REAL
      );

      CREATE TABLE IF NOT EXISTS recoveries (
        id TEXT PRIMARY KEY,
        billNumber TEXT,
        billDate TEXT,
        recoveryDate TEXT,
        type TEXT,
        billAmountAtRecovery REAL,
        recoveryAmount REAL,
        remainingAmount REAL,
        FOREIGN KEY(billNumber) REFERENCES bills(billNumber) ON DELETE CASCADE
      );
    `);
    persist();
  } catch (err) {
    console.error("Database: Schema creation failed.", err);
    throw err;
  }
};

/**
 * Database Settings Helpers
 */
export const getSetting = (key: string): string | null => {
  if (!db) return null;
  try {
    const result = executeQuery("SELECT value FROM settings WHERE key = ?", [key]);
    return result.length > 0 ? (result[0] as any).value : null;
  } catch (e) {
    return null;
  }
};

export const setSetting = (key: string, value: string) => {
  if (!db) return;
  runCommand("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", [key, value]);
};

/**
 * Saves binary state to IndexedDB.
 */
const persist = async () => {
  if (!db) return;
  try {
    const binaryArray = db.export();
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const idb = request.result;
      if (!idb.objectStoreNames.contains(STORE_NAME)) {
        idb.createObjectStore(STORE_NAME);
      }
    };

    request.onsuccess = () => {
      const idb = request.result;
      try {
        const transaction = idb.transaction(STORE_NAME, 'readwrite');
        transaction.objectStore(STORE_NAME).put(binaryArray, 'current');
      } catch (e) {
        console.warn("IndexedDB Write Error:", e);
      }
    };
  } catch (e) {
    console.error("Persistence failed:", e);
  }
};

const loadFromIndexedDB = (): Promise<ArrayBuffer | null> => {
  return new Promise((resolve) => {
    try {
      const request = indexedDB.open(DB_NAME, 1);
      request.onupgradeneeded = () => {
        const idb = request.result;
        if (!idb.objectStoreNames.contains(STORE_NAME)) idb.createObjectStore(STORE_NAME);
        resolve(null);
      };
      request.onsuccess = () => {
        const idb = request.result;
        if (!idb.objectStoreNames.contains(STORE_NAME)) { resolve(null); return; }
        const transaction = idb.transaction(STORE_NAME, 'readonly');
        const getRequest = transaction.objectStore(STORE_NAME).get('current');
        getRequest.onsuccess = () => resolve(getRequest.result || null);
        getRequest.onerror = () => resolve(null);
      };
      request.onerror = () => resolve(null);
    } catch (e) { resolve(null); }
  });
};

export const executeQuery = (sql: string, params: any[] = []) => {
  if (!db) return [];
  try {
    const stmt = db.prepare(sql);
    stmt.bind(params);
    const results = [];
    while (stmt.step()) results.push(stmt.getAsObject());
    stmt.free();
    return results;
  } catch (e) {
    console.error(`SQL Select Error: ${sql}`, e);
    return [];
  }
};

export const runCommand = (sql: string, params: any[] = []) => {
  if (!db) return;
  try {
    db.run(sql, params);
    persist();
  } catch (e) {
    console.error(`SQL Write Error: ${sql}`, e);
    throw e;
  }
};

/**
 * Exports all data for cloud syncing
 */
export const getAllDataForSync = () => {
  return {
    bills: executeQuery("SELECT * FROM bills"),
    recoveries: executeQuery("SELECT * FROM recoveries"),
    customers: executeQuery("SELECT * FROM customers"),
    obs: executeQuery("SELECT * FROM obs"),
    timestamp: new Date().toISOString(),
    version: "1.0"
  };
};

export const importJsonData = (data: any) => {
  if (!db) return;
  try {
    // Truncate tables
    db.run("DELETE FROM bills");
    db.run("DELETE FROM recoveries");
    db.run("DELETE FROM customers");
    db.run("DELETE FROM obs");

    // Insert Bills
    if (Array.isArray(data.bills)) {
      data.bills.forEach((b: any) => {
        db.run(`INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance) VALUES (?,?,?,?,?,?,?,?,?,?,?)`, 
          [b.id, b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.recovery, b.balance]);
      });
    }

    // Insert Recoveries
    if (Array.isArray(data.recoveries)) {
      data.recoveries.forEach((r: any) => {
        db.run(`INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount) VALUES (?,?,?,?,?,?,?,?)`,
          [r.id, r.billNumber, r.billDate, r.recoveryDate, r.type, r.billAmountAtRecovery, r.recoveryAmount, r.remainingAmount]);
      });
    }

    // Insert Customers
    if (Array.isArray(data.customers)) {
      data.customers.forEach((c: any) => {
        db.run(`INSERT INTO customers (id, code, name, address, obCode) VALUES (?,?,?,?,?)`,
          [c.id, c.code, c.name, c.address, c.obCode]);
      });
    }

    // Insert OBs
    if (Array.isArray(data.obs)) {
      data.obs.forEach((o: any) => {
        db.run(`INSERT INTO obs (id, code, name, phone) VALUES (?,?,?,?)`,
          [o.id, o.code, o.name, o.phone]);
      });
    }

    persist();
    return true;
  } catch (err) {
    console.error("Data import failed:", err);
    throw err;
  }
};

export const importSqliteFile = async (buffer: Uint8Array) => {
  if (!SQL_LIB) return;
  try {
    const newDb = new SQL_LIB.Database(buffer);
    db = newDb;
    createSchema(); // Ensure schema is up to date
    persist();
    return true;
  } catch (err) {
    console.error("SQLite import failed:", err);
    throw err;
  }
};

export const getDatabaseFile = () => db ? db.export() : null;

export const resetDatabase = async () => {
  try {
    const request = indexedDB.deleteDatabase(DB_NAME);
    request.onsuccess = () => window.location.reload();
    request.onerror = () => alert("Reset failed.");
  } catch (e) {
    alert("Reset failed. Try clearing your browser cache.");
  }
};

import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType, SyncState } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting, getAllDataForSync } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';
import CloudSyncPage from './components/CloudSyncPage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes' | 'sync';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  // Cloud Sync State
  const [syncUrl, setSyncUrl] = useState<string>('');
  const [syncState, setSyncState] = useState<SyncState>({ lastSync: null, status: 'idle' });

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      console.info("App: Starting initialization setup...");
      try {
        await initDB();

        // Load configuration from SQLite settings table
        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUrl = getSetting('cloud_sync_url');
        if (savedUrl) setSyncUrl(savedUrl);

        const savedLastSync = getSetting('last_sync_time');
        if (savedLastSync) setSyncState(prev => ({ ...prev, lastSync: savedLastSync }));

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) {
          try {
            setCurrentUser(JSON.parse(savedUserJson));
          } catch (e) {
            console.warn("App: Failed to parse active session, clearing stale data.");
            runCommand("DELETE FROM settings WHERE key = 'active_session'");
          }
        }

        setIsDbReady(true);
        refreshData();
        console.info("App: Initialization complete.");
      } catch (err: any) {
        console.error("App: Initialization failed during setup hook:", err);
        setDbError(err.message || "Unknown system failure during relational engine mounting.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("App: Data refresh failed.", e);
    }
  };

  const handleSyncToCloud = async () => {
    if (!syncUrl) {
        alert("Please provide a Sync URL in settings.");
        return;
    }
    setSyncState(prev => ({ ...prev, status: 'syncing' }));

    try {
      const payload = getAllDataForSync();
      const response = await fetch(syncUrl, {
        method: 'POST',
        mode: 'cors',
        headers: { 
            'Content-Type': 'text/plain;charset=utf-8' 
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

      const now = new Date().toLocaleString();
      setSyncState({ lastSync: now, status: 'success' });
      setSetting('last_sync_time', now);
      alert("Sync Successful! Data has been pushed to the cloud.");
    } catch (err: any) {
      console.error("Sync Error:", err);
      let errorMsg = err.message;
      if (err.message === "Failed to fetch") {
          errorMsg = "Network Error: This usually means the URL is wrong, the server is down, or CORS is blocking the request.";
      }
      setSyncState(prev => ({ ...prev, status: 'error', errorMessage: errorMsg }));
      alert("Cloud Sync Failed: " + errorMsg);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
    setSetting('app_theme', newTheme);
  };

  const handleCurrencyChange = (newSymbol: string) => {
    setCurrencySymbol(newSymbol);
    setSetting('app_currency', newSymbol);
  };

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setSetting('active_session', JSON.stringify(user));
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    runCommand("DELETE FROM settings WHERE key = 'active_session'");
  };

  const addBill = (bill: Omit<Bill, 'id' | 'recovery' | 'balance'>, stayOnPage: boolean = false) => {
    const id = generateId();
    runCommand(`
      INSERT INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, bill.date, bill.customerCode, bill.obCode, bill.billNumber, bill.shopName, bill.shopAddress, bill.billType, bill.billAmount, 0, bill.billAmount]);
    refreshData();
    if (!stayOnPage) {
      setActiveTab('ledger');
    }
  };

  const addCustomer = (customer: Omit<Customer, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO customers (id, code, name, address, obCode)
      VALUES (?, ?, ?, ?, ?)
    `, [id, customer.code, customer.name, customer.address, customer.obCode]);
    refreshData();
  };

  const deleteCustomer = (id: string) => {
    if (window.confirm("Delete customer? This will not remove their historical bills.")) {
      runCommand("DELETE FROM customers WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addOB = (ob: Omit<OrderBooker, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO obs (id, code, name, phone)
      VALUES (?, ?, ?, ?)
    `, [id, ob.code, ob.name, ob.phone]);
    refreshData();
  };

  const deleteOB = (id: string) => {
    if (window.confirm("Delete Order Booker?")) {
      runCommand("DELETE FROM obs WHERE id = ?", [id]);
      refreshData();
    }
  };

  const updateBill = (updated: Bill) => {
    runCommand(`
      UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=?
      WHERE id=?
    `, [updated.date, updated.customerCode, updated.obCode, updated.billNumber, updated.shopName, updated.shopAddress, updated.billType, updated.billAmount, updated.recovery, updated.balance, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('ledger');
  };

  const deleteBill = (id: string) => {
    if (window.confirm("Delete this bill and its recoveries?")) {
      const bill = bills.find(b => b.id === id);
      if (bill) runCommand("DELETE FROM recoveries WHERE billNumber = ?", [bill.billNumber]);
      runCommand("DELETE FROM bills WHERE id = ?", [id]);
      refreshData();
    }
  };

  const addRecovery = (recovery: Omit<Recovery, 'id'>) => {
    const id = generateId();
    runCommand(`
      INSERT INTO recoveries (id, billNumber, billDate, recoveryDate, type, billAmountAtRecovery, recoveryAmount, remainingAmount)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `, [id, recovery.billNumber, recovery.billDate, recovery.recoveryDate, recovery.type, recovery.billAmountAtRecovery, recovery.recoveryAmount, recovery.remainingAmount]);

    runCommand(`UPDATE bills SET recovery = recovery + ?, balance = balance - ? WHERE billNumber = ?`, 
      [recovery.recoveryAmount, recovery.recoveryAmount, recovery.billNumber]);

    refreshData();
    setActiveTab('ledger');
  };

  const deleteRecovery = (id: string) => {
    if (window.confirm("Delete this recovery?")) {
      const rec = recoveries.find(r => r.id === id);
      if (rec) {
        runCommand(`UPDATE bills SET recovery = recovery - ?, balance = balance + ? WHERE billNumber = ?`, 
          [rec.recoveryAmount, rec.recoveryAmount, rec.billNumber]);
        runCommand("DELETE FROM recoveries WHERE id = ?", [id]);
      }
      refreshData();
    }
  };

  const updateCustomer = (updated: Customer) => {
    runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, 
      [updated.code, updated.name, updated.address, updated.obCode, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('customers');
  };

  const updateOB = (updated: OrderBooker) => {
    runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, 
      [updated.code, updated.name, updated.phone, updated.id]);
    refreshData();
    setEditingItem(null);
    setActiveTab('obs');
  };

  const handleBulkImportBills = (newBills: Omit<Bill, 'id' | 'recovery' | 'balance'>[]) => {
    newBills.forEach(b => {
      runCommand(`
        INSERT OR IGNORE INTO bills (id, date, customerCode, obCode, billNumber, shopName, shopAddress, billType, billAmount, recovery, balance)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
      `, [generateId(), b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.billAmount]);
    });
    refreshData();
    setActiveTab('ledger');
  };

  const handleBulkImportCustomers = (newCustomers: Omit<Customer, 'id'>[]) => {
    newCustomers.forEach(c => {
      runCommand(`INSERT OR IGNORE INTO customers (id, code, name, address, obCode) VALUES (?, ?, ?, ?, ?)`, 
        [generateId(), c.code, c.name, c.address, c.obCode]);
    });
    refreshData();
    setActiveTab('customers');
  };

  const handleBulkImportOBs = (newOBs: Omit<OrderBooker, 'id'>[]) => {
    newOBs.forEach(o => {
      runCommand(`INSERT OR IGNORE INTO obs (id, code, name, phone) VALUES (?, ?, ?, ?)`, 
        [generateId(), o.code, o.name, o.phone]);
    });
    refreshData();
    setActiveTab('obs');
  };

  const getThemeColor = () => {
    switch (theme) {
      case 'indigo': return 'bg-indigo-600 shadow-indigo-200';
      case 'emerald': return 'bg-emerald-600 shadow-emerald-200';
      case 'crimson': return 'bg-rose-600 shadow-rose-200';
      case 'amber': return 'bg-amber-500 shadow-amber-200';
      case 'slate': return 'bg-slate-900 shadow-slate-200';
      default: return 'bg-blue-600 shadow-blue-200';
    }
  };

  const getThemeText = () => {
    switch (theme) {
      case 'indigo': return 'text-indigo-600';
      case 'emerald': return 'text-emerald-600';
      case 'crimson': return 'text-rose-600';
      case 'amber': return 'text-amber-600';
      case 'slate': return 'text-slate-900';
      default: return 'text-blue-600';
    }
  };

  const NavItem = ({ id, label, icon }: { id: Tab, label: string, icon: React.ReactNode }) => (
    <button onClick={() => setActiveTab(id)} className={`w-full flex items-center gap-3 px-6 py-4 rounded-2xl font-bold transition-all ${activeTab === id ? `${getThemeColor()} text-white shadow-lg` : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}>
      {icon}
      <span className="text-sm">{label}</span>
    </button>
  );

  if (dbError) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
      <div className="bg-white p-10 rounded-[40px] shadow-2xl border border-rose-100 max-w-lg text-center">
        <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-full flex items-center justify-center mx-auto mb-6">
          <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
        </div>
        <h2 className="text-2xl font-black text-slate-900 mb-2">Engine Boot Failure</h2>
        <p className="text-slate-500 mb-8">{dbError}</p>
        <div className="flex flex-col gap-3">
          <button onClick={() => window.location.reload()} className="w-full bg-blue-600 text-white py-4 rounded-2xl font-bold hover:bg-blue-700 transition-all shadow-lg">Retry System Load</button>
          <button onClick={resetDatabase} className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold hover:bg-slate-200 transition-all">Factory Reset Storage</button>
        </div>
      </div>
    </div>
  );

  if (!isDbReady) return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="text-center">
        <div className="w-16 h-16 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mx-auto mb-6 shadow-xl shadow-blue-100"></div>
        <h2 className="text-xl font-black text-slate-900 tracking-tight">System Initialization</h2>
        <p className="text-slate-400 mt-2 font-medium">Mounting Relational Engine (WASM)...</p>
      </div>
    </div>
  );

  if (!currentUser) return <LoginPage onLogin={handleLogin} />;

  const isAdmin = currentUser.role === UserRole.ADMIN;

  return (
    <div className={`min-h-screen bg-slate-50 flex font-sans text-slate-900 theme-${theme}`}>
      <aside className={`w-80 border-r border-slate-100 p-8 flex flex-col gap-10 print:hidden sticky top-0 h-screen overflow-y-auto ${theme === 'indigo' || theme === 'crimson' ? 'bg-slate-900 text-slate-400' : 'bg-white'}`}>
        <div className="px-2">
          <h1 className={`text-2xl font-black tracking-tighter flex items-center gap-2 ${theme === 'indigo' || theme === 'crimson' ? 'text-white' : 'text-slate-900'}`}>
            <div className={`w-8 h-8 rounded-lg flex items-center justify-center text-white text-xs ${theme === 'indigo' || theme === 'crimson' ? 'bg-white/10' : 'bg-slate-900'}`}>BT</div>
            BillTrack <span className={getThemeText()}>Pro</span>
          </h1>
          <div className="flex items-center gap-2 mt-1">
            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Enterprise Ledger</p>
            <div className="flex items-center gap-1 bg-emerald-500/10 px-1.5 py-0.5 rounded text-[8px] font-black text-emerald-500 uppercase">
              <div className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></div> SQLite 3.x
