      <main className="flex-1 p-12 max-w-7xl mx-auto print:p-0 print:max-w-none">
        {activeTab === 'dashboard' && (isAdmin ? <Dashboard bills={bills} recoveries={recoveries} currency={currencySymbol} /> : <UserDashboard user={currentUser} bills={bills} recoveries={recoveries} currency={currencySymbol} />)}
        {activeTab === 'bills' && <BillForm customers={customers} obs={obs} onSubmit={addBill} currency={currencySymbol} onAddCustomer={addCustomer} />}
        {activeTab === 'recovery' && <RecoveryForm bills={bills} onSubmit={addRecovery} currency={currencySymbol} />}
        {isAdmin && (
          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} currency={currencySymbol} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} onAddCustomer={addCustomer} onDeleteCustomer={deleteCustomer} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} onAddOB={addOB} onDeleteOB={deleteOB} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} currency={currencySymbol} />}
            {activeTab === 'import' && <ImportPage onImportBills={handleBulkImportBills} onImportCustomers={handleBulkImportCustomers} onImportOBs={handleBulkImportOBs} customers={customers} obs={obs} currency={currencySymbol} />}
            {activeTab === 'sync' && <CloudSyncPage syncUrl={syncUrl} setSyncUrl={setSyncUrl} syncState={syncState} onSyncNow={handleSyncToCloud} onPullNow={handlePullFromCloud} refreshData={refreshData} />}
            {activeTab === 'themes' && <ThemePage currentTheme={theme} currentCurrency={currencySymbol} onThemeChange={handleThemeChange} onCurrencyChange={handleCurrencyChange} />}
            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} currency={currencySymbol} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage item={editingItem} customers={customers} obs={obs} bills={bills} currency={currencySymbol} onUpdateBill={updateBill} onUpdateRecovery={() => {}} onUpdateCustomer={updateCustomer} onUpdateOB={updateOB} onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { SyncState } from '../types';
import { getAllDataForSync, setSetting, importJsonData, getDatabaseFile, importSqliteFile } from '../database';

interface Props {
  syncUrl: string;
  setSyncUrl: (url: string) => void;
  syncState: SyncState;
  onSyncNow: (isTest?: boolean) => void;
  onPullNow: () => void;
  refreshData: () => void;
}

const CloudSyncPage: React.FC<Props> = ({ syncUrl, setSyncUrl, syncState, onSyncNow, onPullNow, refreshData }) => {
  const [localUrl, setLocalUrl] = useState(syncUrl);
  const [activeTab, setActiveTab] = useState<'cloud' | 'manual'>('cloud');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const sqliteInputRef = useRef<HTMLInputElement>(null);

  const handleUpdateUrl = (e: React.FormEvent) => {
    e.preventDefault();
    setSyncUrl(localUrl);
    setSetting('cloud_sync_url', localUrl);
