import React, { useState, useEffect } from 'react';
import { Bill, Recovery, Customer, OrderBooker, User, UserRole, ThemeType, SyncState } from './types';
import { initDB, executeQuery, runCommand, resetDatabase, getSetting, setSetting, getAllDataForSync, importJsonData } from './database';
import Dashboard from './components/Dashboard';
import UserDashboard from './components/UserDashboard';
import LoginPage from './components/LoginPage';
import BillForm from './components/BillForm';
import RecoveryForm from './components/RecoveryForm';
import Ledger from './components/Ledger';
import CustomerForm from './components/CustomerForm';
import OrderBookerForm from './components/OrderBookerForm';
import Summary from './components/Summary';
import ImportPage from './components/ImportPage';
import EditEntryPage from './components/EditEntryPage';
import TodayReport from './components/TodayReport';
import OBLedger from './components/OBLedger';
import CustomerLedger from './components/CustomerLedger';
import ThemePage from './components/ThemePage';
import CloudSyncPage from './components/CloudSyncPage';

type Tab = 'dashboard' | 'bills' | 'recovery' | 'ledger' | 'customers' | 'obs' | 'summary' | 'import' | 'edit' | 'today' | 'ob-ledger' | 'customer-ledger' | 'themes' | 'sync';

const generateId = () => crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).substring(2, 15);

const App: React.FC = () => {
  const [isDbReady, setIsDbReady] = useState(false);
  const [dbError, setDbError] = useState<string | null>(null);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [bills, setBills] = useState<Bill[]>([]);
  const [recoveries, setRecoveries] = useState<Recovery[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [obs, setObs] = useState<OrderBooker[]>([]);
  const [theme, setTheme] = useState<ThemeType>('blue');
  const [currencySymbol, setCurrencySymbol] = useState<string>('Rs.');

  // Cloud Sync State
  const [syncUrl, setSyncUrl] = useState<string>('');
  const [syncState, setSyncState] = useState<SyncState>({ lastSync: null, status: 'idle' });

  const [editingItem, setEditingItem] = useState<{ type: 'bill' | 'recovery' | 'customer' | 'ob', data: any } | null>(null);

  // Initialize SQLite and Load Config
  useEffect(() => {
    const setup = async () => {
      console.info("App: Starting initialization setup...");
      try {
        await initDB();

        const savedTheme = getSetting('app_theme') as ThemeType;
        if (savedTheme) setTheme(savedTheme);

        const savedCurrency = getSetting('app_currency');
        if (savedCurrency) setCurrencySymbol(savedCurrency);

        const savedUrl = getSetting('cloud_sync_url');
        if (savedUrl) setSyncUrl(savedUrl);

        const savedLastSync = getSetting('last_sync_time');
        if (savedLastSync) setSyncState(prev => ({ ...prev, lastSync: savedLastSync }));

        const savedUserJson = getSetting('active_session');
        if (savedUserJson) {
          try {
            setCurrentUser(JSON.parse(savedUserJson));
          } catch (e) {
            console.warn("App: Failed to parse active session, clearing stale data.");
            runCommand("DELETE FROM settings WHERE key = 'active_session'");
          }
        }

        setIsDbReady(true);
        refreshData();
        console.info("App: Initialization complete.");
      } catch (err: any) {
        console.error("App: Initialization failed during setup hook:", err);
        setDbError(err.message || "Unknown system failure during relational engine mounting.");
      }
    };
    setup();
  }, []);

  const refreshData = () => {
    try {
      setBills(executeQuery("SELECT * FROM bills ORDER BY date DESC") as Bill[]);
      setRecoveries(executeQuery("SELECT * FROM recoveries ORDER BY recoveryDate DESC") as Recovery[]);
      setCustomers(executeQuery("SELECT * FROM customers ORDER BY name ASC") as Customer[]);
      setObs(executeQuery("SELECT * FROM obs ORDER BY name ASC") as OrderBooker[]);
    } catch (e) {
      console.error("App: Data refresh failed.", e);
    }
  };

  const handleSyncToCloud = async (isTest: boolean = false) => {
    if (!syncUrl) {
        alert("Please provide a Sync URL in settings.");
        return;
    }

    if (window.location.protocol === 'file:') {
      const msg = "Local Protocol Block: You are running this app via 'file://'. Modern browsers block network requests from local files for security. Please run the app using a local server (e.g., VS Code Live Server or 'npx serve .').";
      setSyncState(prev => ({ ...prev, status: 'error', errorMessage: msg }));
      alert(msg);
      return;
    }

    setSyncState(prev => ({ ...prev, status: 'syncing', errorMessage: undefined }));

    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 20000);

      const payload = isTest ? { test: true, timestamp: new Date().toISOString() } : getAllDataForSync();

      // We use 'text/plain' to avoid CORS preflight 'OPTIONS' request which many simple servers fail to handle
      const response = await fetch(syncUrl, {
        method: 'POST',
        mode: 'cors',
        credentials: 'omit',
        redirect: 'follow',
        headers: { 
            'Content-Type': 'text/plain' 
        },
        body: JSON.stringify(payload),
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        const text = await response.text();
        throw new Error(`HTTP ${response.status}: ${text || response.statusText}`);
      }

      const now = new Date().toLocaleString();
      setSyncState({ lastSync: now, status: 'success' });
      setSetting('last_sync_time', now);
      if (isTest) alert("Connection Test Successful!");
      else alert("Sync Successful! Data has been pushed to the cloud.");
    } catch (err: any) {
      console.error("Sync Error:", err);
      let errorMsg = err.name === 'AbortError' ? "Request timed out (20s)." : err.message;

      if (err.message === "Failed to fetch") {
          errorMsg = "Network Error (Failed to fetch): This is usually caused by CORS security or running from a 'file://' protocol. Ensure your server allows cross-origin requests and you are using http://localhost.";
      }

      setSyncState(prev => ({ ...prev, status: 'error', errorMessage: errorMsg }));
      alert("Cloud Sync Failed: " + errorMsg);
    }
  };

  const handlePullFromCloud = async () => {
    if (!syncUrl) { alert("Please provide a Sync URL."); return; }
    if (!window.confirm("Pulling from cloud will OVERWRITE your local data. Proceed?")) return;

    setSyncState(prev => ({ ...prev, status: 'syncing', errorMessage: undefined }));
    try {
      const response = await fetch(syncUrl, { 
        method: 'GET',
        mode: 'cors',
        credentials: 'omit'
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);

      const data = await response.json();
      if (data && (data.bills || data.customers)) {
        importJsonData(data);
        refreshData();
        setSyncState(prev => ({ ...prev, status: 'success', lastSync: new Date().toLocaleString() }));
        alert("Data successfully restored from cloud!");
      } else {
        throw new Error("Endpoint returned invalid or empty data structure.");
      }
    } catch (err: any) {
      console.error("Pull Error:", err);
      setSyncState(prev => ({ ...prev, status: 'error', errorMessage: err.message }));
      alert("Pull Failed: " + err.message);
    }
  };

  const handleThemeChange = (newTheme: ThemeType) => {
    setTheme(newTheme);
