          <>
            {activeTab === 'ledger' && <Ledger bills={bills} recoveries={recoveries} currency={currencySymbol} onEditBill={(b) => { setEditingItem({ type: 'bill', data: b }); setActiveTab('edit'); }} onDeleteBill={deleteBill} onDeleteRecovery={deleteRecovery} />}
            {activeTab === 'customers' && <CustomerForm customers={customers} onAddCustomer={addCustomer} onDeleteCustomer={(id) => { runCommand("DELETE FROM customers WHERE id=?", [id]); refreshData(); }} obs={obs} onEdit={(c) => { setEditingItem({ type: 'customer', data: c }); setActiveTab('edit'); }} />}
            {activeTab === 'obs' && <OrderBookerForm obs={obs} onAddOB={addOB} onDeleteOB={(id) => { runCommand("DELETE FROM obs WHERE id=?", [id]); refreshData(); }} onEdit={(o) => { setEditingItem({ type: 'ob', data: o }); setActiveTab('edit'); }} />}
            {activeTab === 'summary' && <Summary bills={bills} obs={obs} currency={currencySymbol} />}
