            {activeTab === 'today' && <TodayReport bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'ob-ledger' && <OBLedger bills={bills} recoveries={recoveries} obs={obs} currency={currencySymbol} />}
            {activeTab === 'customer-ledger' && <CustomerLedger bills={bills} recoveries={recoveries} customers={customers} currency={currencySymbol} />}
          </>
        )}
        {activeTab === 'edit' && editingItem && (
          <EditEntryPage 
            item={editingItem} customers={customers} obs={obs} bills={bills} currency={currencySymbol} 
            onUpdateBill={(b) => { runCommand(`UPDATE bills SET date=?, customerCode=?, obCode=?, billNumber=?, shopName=?, shopAddress=?, billType=?, billAmount=?, recovery=?, balance=? WHERE id=?`, [b.date, b.customerCode, b.obCode, b.billNumber, b.shopName, b.shopAddress, b.billType, b.billAmount, b.recovery, b.balance, b.id]); refreshData(); setEditingItem(null); setActiveTab('ledger'); }} 
            onUpdateRecovery={() => {}} 
            onUpdateCustomer={(c) => { runCommand(`UPDATE customers SET code=?, name=?, address=?, obCode=? WHERE id=?`, [c.code, c.name, c.address, c.obCode, c.id]); refreshData(); setEditingItem(null); setActiveTab('customers'); }} 
            onUpdateOB={(o) => { runCommand(`UPDATE obs SET code=?, name=?, phone=? WHERE id=?`, [o.code, o.name, o.phone, o.id]); refreshData(); setEditingItem(null); setActiveTab('obs'); }} 
            onCancel={() => { setEditingItem(null); setActiveTab(isAdmin ? 'ledger' : 'dashboard'); }} 
          />
        )}
      </main>
    </div>
  );
};

