              <NavItem id="sync" label="Cloud Sync" icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999" strokeWidth={2}/></svg>} />
